module.exports=[50151,a=>{"use strict";let b=[{slug:"complete-guide-seai-solar-grant-2026",title:"The Complete Guide to the SEAI Solar Grant in 2026",excerpt:"Everything you need to know about the €1,800 SEAI solar panel grant — eligibility, how to apply, timelines, and how to maximise your savings with the Clean Export Guarantee.",category:"grants",date:"15 Apr 2026",readTime:"12 min read",featured:!0,author:"Cal O'Reilly",iconBg:"bg-amber-400/10",iconColor:"text-amber-400",image:"/blog-seai-grant.webp",content:[{type:"heading",level:2,text:"What Is the SEAI Solar Panel Grant?"},{type:"paragraph",text:"The SEAI solar panel grant in Ireland is **€1,800** in 2026. This government-backed payment from the Sustainable Energy Authority of Ireland covers a significant portion of a typical residential solar PV installation, reducing the out-of-pocket cost for homeowners. The grant is available to owner-occupiers of homes built before 2021 and is paid directly to your installer after completion — no waiting for a refund."},{type:"paragraph",text:"The grant is part of Ireland's broader National Development Plan, which aims to have 70% of electricity generated from renewable sources by 2030. Solar PV is a cornerstone of this strategy, and the SEAI grant is designed to accelerate adoption across the country. Since the scheme launched, tens of thousands of Irish homeowners have successfully applied and received funding for their solar installations."},{type:"callout",variant:"stat",title:"Key Statistic",body:"Over 65,000 Irish homes have received the SEAI solar grant since its inception, with uptake accelerating by 40% year-on-year since 2024."},{type:"heading",level:2,text:"Who Is Eligible for the Grant?"},{type:"paragraph",text:"The SEAI solar grant is available to a wide range of homeowners across Ireland. Understanding the eligibility criteria before you apply can save time and avoid disappointment. Here are the main requirements you need to meet:"},{type:"bulletList",items:["The property must be built before 2021 (new builds completed after this date are not eligible)","You must be the owner of the property, or have permission from the owner to install solar panels","The home must be your primary residence (not a holiday home or rental property)","The property must be located in the Republic of Ireland","Your chosen installer must be a registered SEAI contractor","You must not have previously received a solar PV grant for the same property"]},{type:"paragraph",text:"There is no means testing for this grant — it is available regardless of your income level. Whether you own a detached house in Dublin, a semi-detached home in Cork, or a bungalow in rural Donegal, you can apply provided you meet the criteria above."},{type:"heading",level:2,text:"How Much Is the Grant Worth?"},{type:"paragraph",text:"The standard SEAI solar PV grant in 2026 provides €1,800 towards the cost of your installation. This is a flat-rate grant for a typical domestic system. Unfortunately, the previous battery storage grant of €600 was discontinued — there is currently no standalone SEAI grant for battery storage, which makes choosing the right battery even more important."},{type:"table",headers:["System Component","Grant Amount","Typical Cost","Grant Coverage"],rows:[["Solar PV Panels (standard)","€1,800","€6,000 – €16,000","11% – 30%"],["Battery Storage (up to 6kWh)","No grant","€4,000 – €8,000","N/A"],["Solar PV + Battery Combined","Up to €1,800","€10,000 – €24,000","7.5% – 18%"]]},{type:"callout",variant:"tip",title:"Maximise Your Savings",body:"The SEAI grant can be stacked with the Clean Export Guarantee (CEG), which pays you €0.21/kWh for excess solar energy exported to the grid. Between the grant, bill savings, and CEG earnings, a typical system can pay for itself in 5–7 years."},{type:"heading",level:2,text:"The BER Requirement"},{type:"paragraph",text:"One of the most common stumbling blocks in the application process is the Building Energy Rating (BER) requirement. Since 2023, all grant applicants must have a valid BER assessment either completed before the installation or booked to be carried out within a specified timeframe afterwards."},{type:"paragraph",text:"A BER assessment typically costs between €200 and €350 and provides a rating from A (most efficient) to G (least efficient). The good news is that you do not need to achieve a particular BER rating to qualify for the solar grant — you simply need to have one carried out. In fact, installing solar panels will often improve your BER rating by 1–2 grades, which adds value to your property."},{type:"callout",variant:"warning",title:"Important BER Note",body:"If you plan to get your BER done after installation, you must provide the SEAI with evidence that a BER assessor has been booked before your grant application can be fully processed. Many installers can arrange this for you as part of the package."},{type:"heading",level:2,text:"Step-by-Step Application Process"},{type:"paragraph",text:"Applying for the SEAI solar grant is straightforward, but following the correct sequence is important. Here is the process from start to finish:"},{type:"numberedList",items:["Get quotes from at least 3 SEAI-registered installers. Compare prices, panel brands, warranties, and inverter options.","Choose your installer and agree on a date for the installation. Do not begin installation before getting grant pre-approval.","Apply online through the SEAI portal (seai.ie). You will need your MPRN number (found on your electricity bill), property details, and your chosen installer's SEAI registration number.","Receive your grant offer letter from the SEAI, typically within 4–6 weeks. Review and accept the terms.","Proceed with the solar panel installation. Your installer must complete the work within 8 months of the grant offer date.","After installation, submit your completion documents to the SEAI — this includes the installer's completion certificate, photos of the installation, and your BER assessment.","Receive your grant payment via bank transfer, usually within 6–8 weeks of submitting completion documents."]},{type:"heading",level:2,text:"Common Mistakes to Avoid"},{type:"paragraph",text:"Every year, a significant number of grant applications are delayed or rejected due to easily preventable errors. Here are the most common mistakes we see:"},{type:"bulletList",items:["Starting installation before receiving grant pre-approval — this can invalidate your entire claim","Using an installer who is not SEAI-registered — always verify registration on the SEAI website","Not having a BER assessment completed or booked within the required timeframe","Submitting incomplete documentation — ensure all photos, certificates, and forms are included","Missing the 8-month installation deadline after receiving the grant offer","Applying for the wrong grant category — the solar PV grant is separate from the solar water heating grant"]},{type:"callout",variant:"info",title:"Time-Saving Tip",body:"Many SEAI-registered installers will handle the entire grant application process on your behalf, including the BER booking. Ask about this when getting quotes — it can save you significant admin time and ensure nothing gets missed."},{type:"heading",level:2,text:"2026 Timelines and Budget"},{type:"paragraph",text:"The SEAI solar grant scheme has an annual budget allocated by the government. In recent years, the budget has increased to meet growing demand, but it is still subject to annual review. The 2026 allocation is expected to be €85 million, which should comfortably cover all applications received during the year."},{type:"paragraph",text:"However, it is worth applying early in the year rather than waiting. The application process takes approximately 4–6 weeks for pre-approval, plus 6–8 weeks for payment after completion. Starting your journey in spring means you can have your system installed and generating electricity by summer — when solar output in Ireland is at its peak."},{type:"table",headers:["Timeline Stage","Typical Duration","What Happens"],rows:[["Get Quotes","2–4 weeks","Contact installers, compare quotes, choose installer"],["Grant Application","4–6 weeks","SEAI reviews and issues offer letter"],["Installation","1–2 days","Physical installation on your property"],["BER Assessment","1–2 weeks","Energy rating assessment (if not pre-done)"],["Completion Submission","1–2 weeks","Gather and submit all required documents"],["Grant Payment","6–8 weeks","SEAI processes and pays into your bank"]]},{type:"heading",level:2,text:"How to Maximise Your Total Savings"},{type:"paragraph",text:"The SEAI grant is just the beginning of your savings journey. Here is how to get the absolute maximum financial return from going solar:"},{type:"numberedList",items:["Combine the grant with the Clean Export Guarantee — earn €0.21/kWh for every unit of surplus energy you export to the grid. This alone can add €300–€500 per year to your income.","Shift heavy electricity usage to daylight hours — run washing machines, dishwashers, and charge EVs while your panels are generating.","Consider adding battery storage — while it adds upfront cost, a battery lets you use almost 100% of your generated electricity rather than exporting the excess.","Ensure your system is sized correctly — an oversized system wastes money, while an undersized one leaves savings on the table.","Maintain your panels — occasional cleaning (rain does most of the work in Ireland) and periodic inverter checks will keep output optimal for 25+ years."]},{type:"paragraph",text:"For a typical Irish household with a 6kWp solar PV system, the combination of bill savings (€800–€1,200/year), CEG earnings (€300–€500/year), and the €1,800 SEAI grant can deliver a full return on investment within 5 to 7 years. After that, every kilowatt-hour generated is essentially free electricity for the remaining 20+ year lifespan of your panels."},{type:"divider"},{type:"cta",text:"Check Your Solar Eligibility — Get a Free Quote",href:"/#calculator"}]},{slug:"how-much-do-solar-panels-cost-ireland-2026",title:"How Much Do Solar Panels Cost in Ireland? (2026 Prices)",excerpt:"A transparent breakdown of solar panel costs in Ireland for 2026 — from 4kWp to 10kWp systems, including installation, grants, and what affects the final price.",category:"savings",date:"12 Apr 2026",readTime:"8 min read",author:"Cal O'Reilly",iconBg:"bg-emerald-400/10",iconColor:"text-emerald-400",image:"/blog-solar-costs.webp",content:[{type:"heading",level:2,text:"Average Solar Panel Costs in Ireland (2026)"},{type:"paragraph",text:"Solar panels in Ireland cost between **€4,200 and €14,200 after the €1,800 SEAI grant** in 2026. A standard 4kWp system costs approximately €4,200–€6,200, a 6kWp system costs €6,700–€9,200, and a 10kWp system with battery costs €10,200–€14,200. Prices have fallen roughly 20–30% over the past five years as the market has matured, making 2026 the most affordable time to go solar."},{type:"paragraph",text:"The Irish solar market has matured significantly over the past few years. Increased competition, improvements in panel efficiency, and streamlined installation processes have all contributed to a steady decline in prices. A standard residential solar PV system now costs roughly 20–30% less than it did just five years ago."},{type:"callout",variant:"stat",title:"Price Range Overview",body:"The average cost of a solar panel system in Ireland in 2026 ranges from €6,000 for a small 4kWp system to €16,000 for a large 10kWp system with battery storage. After the €1,800 SEAI grant, your net cost drops to between €4,200 and €14,200."},{type:"heading",level:2,text:"Cost Breakdown by System Size"},{type:"paragraph",text:"Solar panel systems are measured in kilowatt-peak (kWp), which represents the maximum power output under ideal conditions. The right system size depends on your roof space, electricity consumption, and budget. Here is a detailed breakdown of costs for the three most popular system sizes in Ireland:"},{type:"table",headers:["System Size","Number of Panels","Gross Cost (Before Grant)","After €1,800 Grant","Typical Annual Savings"],rows:[["4kWp","10–12 panels","€6,000 – €8,000","€4,200 – €6,200","€600 – €900"],["6kWp","14–16 panels","€8,500 – €11,000","€6,700 – €9,200","€800 – €1,200"],["10kWp","22–26 panels","€12,000 – €16,000","€10,200 – €14,200","€1,200 – €1,800"]]},{type:"paragraph",text:"The 6kWp system is by far the most popular choice for Irish households, as it provides an excellent balance between upfront cost, roof space requirements, and annual savings. It is large enough to cover a significant portion of the average Irish household's annual electricity consumption (approximately 4,200 kWh) while remaining affordable."},{type:"heading",level:2,text:"What Affects the Price?"},{type:"paragraph",text:"No two solar installations are exactly alike. Several factors influence the final price you will pay, and understanding them helps you evaluate quotes fairly:"},{type:"bulletList",items:["Panel quality and brand — Tier-1 panels (LONGi, Jinko, Trina) cost more than lesser-known brands but offer higher efficiency, better warranties, and proven long-term performance","Inverter type — String inverters are cheapest, microinverters cost more but offer panel-level optimisation (ideal for partially shaded roofs)","Roof complexity — A simple pitched roof with clear access is cheapest to install. Multiple roof planes, flat roofs, or difficult access add €500–€2,000","Scaffold requirements — Most installations require scaffolding, which typically costs €300–€600 extra for two-storey homes","Electrical upgrades — Older homes may need a consumer unit (fuse board) upgrade or new cabling, adding €300–€1,000","Battery storage — Adding a solar battery adds €4,000–€8,000 depending on capacity and brand","Location — Installations in Dublin and other major cities tend to be slightly more expensive than rural areas due to higher labour costs"]},{type:"heading",level:2,text:"Hidden Costs to Watch For"},{type:"paragraph",text:"While reputable installers provide comprehensive quotes that include everything, it is worth being aware of potential additional costs that may not be immediately obvious:"},{type:"callout",variant:"warning",title:"Watch Out For",body:"Some very cheap quotes may exclude scaffolding, electrical upgrades, or BER assessment costs. Always ask for a fully itemised quote that breaks down every cost component so you can compare like-for-like between installers."},{type:"bulletList",items:["BER Assessment: €200–€350 (required for the SEAI grant)","ECS Registration: €250–€500 (required to connect your system to the grid)","Smart meter upgrade: Usually free from ESB Networks, but may involve a wait time of 4–8 weeks","Scaffolding: €300–€600 for typical two-storey homes","Ground-mounted systems: €2,000–€5,000 more than roof-mounted equivalents","Bird protection: €200–€400 if pigeons are known to nest under panels in your area"]},{type:"heading",level:2,text:"ROI Calculations: When Do Solar Panels Pay for Themselves?"},{type:"paragraph",text:"The return on investment (ROI) for solar panels in Ireland has improved dramatically. With current electricity prices averaging €0.35–€0.45/kWh (including standing charges and VAT), a well-sized system can deliver a payback period of just 5–7 years. Here is a detailed ROI calculation for the three most common system sizes:"},{type:"table",headers:["Metric","4kWp System","6kWp System","10kWp System"],rows:[["Net Cost (after grant)","€5,100","€7,950","€12,200"],["Annual Bill Savings","€750","€1,000","€1,500"],["CEG Export Earnings","€150","€250","€400"],["Total Annual Savings","€900","€1,250","€1,900"],["Payback Period","~5.7 years","~6.4 years","~6.4 years"],["25-Year Net Profit","€17,400","€23,300","€35,300"]]},{type:"callout",variant:"tip",title:"ROI Boost",body:"If electricity prices continue to rise (as forecast), your payback period could be even shorter. The above calculations assume constant prices — if electricity reaches €0.50/kWh, the 6kWp system pays for itself in under 5 years."},{type:"heading",level:2,text:"Is Now the Right Time to Buy?"},{type:"paragraph",text:"Solar panel prices in Ireland have stabilised after the supply chain disruptions of 2022–2023. While there are no dramatic price drops expected, the current market offers excellent value for money. The combination of the €1,800 SEAI grant, the Clean Export Guarantee, and rising electricity prices makes 2026 an ideal time to invest in solar."},{type:"paragraph",text:"Waiting for prices to fall further is a risky strategy — every month you delay is a month of missed electricity savings. For homeowners with a suitable roof, the best time to install solar panels is now."},{type:"divider"},{type:"cta",text:"Get a Personalised Solar Quote for Your Home",href:"/#calculator"}]},{slug:"solar-panels-in-winter-do-they-work",title:"Solar Panels in Winter: Do They Actually Work?",excerpt:"A common myth in Ireland is that solar panels are useless in winter. The truth might surprise you — panels still generate 30-50% of their summer output during the darker months.",category:"guides",date:"8 Apr 2026",readTime:"6 min read",author:"Cal O'Reilly",iconBg:"bg-sky-400/10",iconColor:"text-sky-400",image:"/blog-solar-winter.webp",content:[{type:"heading",level:2,text:"The Myth vs The Reality"},{type:"paragraph",text:"**Yes, solar panels absolutely work during Irish winters.** A typical 6kWp system generates approximately 30–50% of its summer output between November and February — producing 150–250 kWh in December alone. Solar panels work on daylight, not direct sunshine, so even on overcast winter days they generate meaningful electricity. Modern panels are specifically designed for low-light conditions like Ireland's climate."},{type:"paragraph",text:"Solar panels do not need direct sunlight to generate electricity. They work on daylight, not sunshine. Even on a completely overcast Irish winter day, your panels will still produce a meaningful amount of power. Think of it this way: you can still get sunburned on a cloudy day — the UV radiation is still there, just diffused. Solar panels work on a similar principle."},{type:"callout",variant:"stat",title:"Winter Output in Ireland",body:"A typical 6kWp solar PV system in Ireland generates approximately 30–50% of its summer output during the winter months (November through February). While this is less than summer, it still contributes meaningfully to your electricity needs."},{type:"heading",level:2,text:"How Much Do Solar Panels Generate in Winter?"},{type:"paragraph",text:"To give you a realistic picture, let us look at the actual monthly generation figures for a typical 6kWp system installed on a south-facing roof in Ireland:"},{type:"table",headers:["Month","Avg Daily Output (kWh)","Monthly Total (kWh)","% of Peak Month"],rows:[["January","5–8 kWh","150–250 kWh","30%"],["February","7–10 kWh","200–280 kWh","35%"],["March","10–15 kWh","310–460 kWh","55%"],["April","14–19 kWh","420–570 kWh","70%"],["May","18–25 kWh","560–780 kWh","90%"],["June","20–28 kWh","600–840 kWh","100%"],["July","19–26 kWh","590–810 kWh","95%"],["August","16–23 kWh","500–710 kWh","85%"],["September","12–17 kWh","360–510 kWh","65%"],["October","8–13 kWh","250–400 kWh","45%"],["November","5–8 kWh","150–240 kWh","28%"],["December","4–7 kWh","120–220 kWh","25%"]]},{type:"paragraph",text:"As you can see, winter generation is lower — but it is far from zero. A 6kWp system will still produce 150–250 kWh in December, which is enough to cover a significant portion of your baseline electricity needs like lighting, fridge, and electronics."},{type:"heading",level:2,text:"Why Winter Isn't as Bad as You Think"},{type:"paragraph",text:"There are several factors that work in your favour during the Irish winter:"},{type:"bulletList",items:["Cold temperatures improve panel efficiency — solar panels actually perform better in cold weather. For every degree above 25°C, panel efficiency drops by about 0.3–0.4%. A crisp winter day at 5°C is ideal for solar generation.","Diffuse light is still useful — Irish winter skies are often uniformly overcast, which creates consistent diffuse light that modern panels are designed to capture effectively.","Rain cleans your panels — Irish winter rain naturally washes away dust, pollen, and bird droppings that can reduce panel output by 5–15% during drier months.","Shorter days, but still 7–8 hours of daylight — Even in late December, Ireland gets approximately 7.5 hours of daylight, providing a meaningful generation window.","Winter electricity usage is higher — You use more electricity in winter (heating, lighting, longer indoor time), so the solar energy you do generate is immediately valuable and rarely wasted."]},{type:"heading",level:2,text:"Net Metering: Winter's Secret Advantage"},{type:"paragraph",text:"The introduction of the Clean Export Guarantee (CEG) and smart meters in Ireland has fundamentally changed the winter equation. With net metering, you effectively use the national grid as a battery. Here is how it works:"},{type:"paragraph",text:"During summer, your panels generate more electricity than you use. The excess is exported to the grid, and you earn €0.21 per kWh through the CEG. In winter, when your panels generate less, you draw more from the grid. The system effectively balances out over the course of a year, and the CEG payments you earn in summer help offset your higher winter electricity bills."},{type:"callout",variant:"tip",title:"Smart Meter Advantage",body:"Having a smart meter installed means you can access the best export tariffs and potentially sign up for time-of-use electricity plans. Some plans offer cheaper electricity at night, which can further reduce your costs if you have battery storage or an EV."},{type:"heading",level:2,text:"Tips to Maximise Winter Generation"},{type:"paragraph",text:"While you cannot control the weather, there are practical steps you can take to squeeze the maximum possible output from your panels during winter:"},{type:"numberedList",items:["Keep panels clean — While rain does most of the work, a gentle hose-down during extended dry spells (yes, even in winter) can maintain peak output.","Avoid shading — Trim any overhanging tree branches. Winter sun is lower in the sky, so shadows cast by trees or buildings are longer and can have a greater impact.","Monitor your system — Use your inverter's monitoring app to track daily generation. A sudden drop could indicate a fault or shading issue that needs attention.","Time your usage — Shift as much electricity consumption as possible to daylight hours. Run your washing machine, dishwasher, and tumble dryer during the middle of the day when generation is highest.","Consider a battery — If your budget allows, a solar battery lets you store winter generation for evening use, reducing your grid dependence when output is at its lowest."]},{type:"paragraph",text:"The bottom line? Solar panels absolutely work in Irish winters. They will not generate as much as in summer, but they will still produce meaningful amounts of free electricity and contribute to lower bills. The idea that solar is only viable in sunny countries is outdated — Ireland's solar resource is surprisingly good, and modern panel technology is designed specifically for cloudy climates like ours."},{type:"divider"},{type:"cta",text:"See How Much Winter Solar Could Save You",href:"/#calculator"}]},{slug:"clean-export-guarantee-explained",title:"Clean Export Guarantee Explained: Get Paid for Your Excess Solar",image:"/blog-clean-export.webp",excerpt:"The Clean Export Guarantee (CEG) allows you to sell surplus solar electricity back to the grid. Here's how it works, what you'll earn, and which suppliers offer the best rates.",category:"grants",date:"4 Apr 2026",readTime:"7 min read",author:"Cal O'Reilly",iconBg:"bg-amber-400/10",iconColor:"text-amber-400",content:[{type:"heading",level:2,text:"What Is the Clean Export Guarantee?"},{type:"paragraph",text:"The Clean Export Guarantee (CEG) pays Irish homeowners **€0.21 per kilowatt-hour** for surplus solar electricity exported to the grid. This government-backed scheme, launched in 2022, requires energy suppliers to pay you for every unit of excess solar power your panels generate. For a typical 6kWp system, CEG earnings add €250–€378 per year on top of your bill savings — and the payment appears automatically as a credit on your electricity bill via your smart meter."},{type:"paragraph",text:"Under the CEG, energy suppliers are required to offer a payment rate for every kilowatt-hour (kWh) of electricity you export. The scheme is designed to make solar panels financially viable for everyone — not just those who can use all of their generated electricity during the day. It effectively turns the national grid into your battery, giving you credit for the power you share with your neighbours."},{type:"callout",variant:"stat",title:"Current CEG Rate",body:"The minimum CEG rate in 2026 is €0.21 per kWh, set by the Commission for Regulation of Utilities (CRU). Some suppliers offer higher rates as part of competitive tariffs, so it pays to shop around."},{type:"heading",level:2,text:"How the CEG Works in Practice"},{type:"paragraph",text:"The mechanics of the Clean Export Guarantee are straightforward, but understanding how the money flows is important for maximising your returns:"},{type:"numberedList",items:["Your solar panels generate electricity during daylight hours.","Any electricity you use in your home is free — it never passes through your meter.","Any surplus electricity that your home does not use is automatically exported to the national grid.","Your smart meter measures exactly how much electricity you export.","Your energy supplier calculates your CEG payment based on your exported kilowatt-hours and their tariff rate.","The payment appears as a credit on your electricity bill or as a direct bank payment, depending on your supplier."]},{type:"paragraph",text:"The system is entirely automated — you do not need to do anything to export power. Whenever your panels are generating more than your home is consuming, the excess flows out to the grid automatically. Your smart meter tracks this in real time."},{type:"heading",level:2,text:"Smart Meter Requirement"},{type:"paragraph",text:"To benefit from the CEG, you need a smart meter installed at your property. Smart meters are digital devices that measure your electricity consumption and generation in real time, replacing the old spinning disc meters that could only measure net flow."},{type:"paragraph",text:"The good news is that ESB Networks has been rolling out smart meters across Ireland since 2019, and most homes with solar panels will already have one. If you do not, you can request a free smart meter installation from ESB Networks. The installation typically takes 1–2 hours and involves replacing your existing meter. There is no charge for this service."},{type:"callout",variant:"warning",title:"Important",body:"Without a smart meter, your installer can still connect your solar system, but you will not be able to receive CEG payments. Getting a smart meter should be one of your first steps when considering solar. It typically takes 4–8 weeks to get one installed."},{type:"heading",level:2,text:"Best Supplier Rates in 2026"},{type:"paragraph",text:"While the CRU sets a minimum CEG rate of €0.21/kWh, many energy suppliers compete by offering higher rates or additional perks. Here is a comparison of the leading supplier CEG offerings as of early 2026:"},{type:"table",headers:["Supplier","CEG Rate (€/kWh)","Contract Type","Additional Perks"],rows:[["Electric Ireland","€0.21","Variable","€50 signup bonus for solar customers"],["SSE Airtricity","€0.22","12-month fixed","Green energy certificate included"],["Bord Gáis Energy","€0.21","Variable","Dual fuel discount available"],["Energia","€0.24","12-month fixed","Highest standalone rate; online-only tariff"],["Pinergy","€0.21","Variable","No standing charge increase"],["Prepay Power","€0.21","Pay-as-you-go","Smart PAYG compatible"]]},{type:"callout",variant:"tip",title:"Switch and Save",body:"CEG rates are not fixed — suppliers adjust them periodically. Check comparison sites like bonkers.ie and Switcher.ie at least once a year to ensure you are on the best available rate. A rate increase from €0.21 to €0.24/kWh could add €60–€100 per year to your CEG earnings."},{type:"heading",level:2,text:"Realistic Earnings: What Can You Expect?"},{type:"paragraph",text:"CEG earnings depend on the size of your system, your daytime electricity consumption, and the orientation of your panels. A household that uses most of its solar generation during the day will export less (and earn less from CEG) but save more on bills. Conversely, a household that is out during the day will export more and earn more from CEG."},{type:"table",headers:["System Size","Annual Export (kWh)","CEG Earnings at €0.21/kWh","CEG Earnings at €0.24/kWh"],rows:[["4kWp","800–1,200 kWh","€168–€252","€192–€288"],["6kWp","1,200–1,800 kWh","€252–€378","€288–€432"],["10kWp","1,800–2,500 kWh","€378–€525","€432–€600"]]},{type:"callout",variant:"info",title:"The Big Picture",body:"CEG earnings alone (€300–€500/year for a typical 6kWp system) may not seem huge, but remember this is income on top of your bill savings (€800–€1,200/year). Together, they significantly accelerate your return on investment. The CEG essentially ensures that no solar energy goes to waste."},{type:"heading",level:2,text:"How to Register for the CEG"},{type:"paragraph",text:"Registering for the Clean Export Guarantee is a simple process. In most cases, your solar installer will handle the registration as part of your installation package. If not, here are the steps:"},{type:"numberedList",items:["Ensure you have a smart meter installed. Contact ESB Networks at 01 698 5005 if you are unsure.","Once your solar system is installed and commissioned, your installer should register it with ESB Networks as a microgeneration unit (under 11kW).","Contact your energy supplier and inform them you now have a solar PV system. They will update your account to reflect your new export capability.","Ask your supplier to put you on their CEG tariff. They may require a copy of your ESB microgeneration certificate.","Your first CEG payment will typically appear on your next billing cycle after registration."]},{type:"paragraph",text:"The entire registration process usually takes 2–4 weeks from the date of your solar installation. Most installers include CEG registration in their standard installation package, so you may not need to do anything yourself."},{type:"divider"},{type:"cta",text:"Get Solar Installed and Start Earning with CEG",href:"/#calculator"}]},{slug:"east-vs-south-vs-west-facing-roofs-solar",title:"East vs South vs West-Facing Roofs: Which Is Best for Solar?",image:"/blog-roof-orientation.webp",excerpt:"Does your roof face the right way for solar? We compare east, south and west-facing installations with real Irish data to show which orientation delivers the best returns.",category:"guides",date:"28 Mar 2026",readTime:"9 min read",author:"Cal O'Reilly",iconBg:"bg-violet-400/10",iconColor:"text-violet-400",content:[{type:"heading",level:2,text:"Does Roof Orientation Really Matter?"},{type:"paragraph",text:'One of the most common concerns homeowners have when considering solar is whether their roof faces the "right" direction. There is a persistent myth that only south-facing roofs are suitable for solar panels. The reality is far more nuanced — and far more encouraging. Modern solar panels are remarkably effective across a range of orientations, and a north-facing roof is actually the only orientation that is genuinely unsuitable in Ireland.'},{type:"paragraph",text:"In Ireland, we are fortunate to be at a latitude (approximately 53°N) where the sun travels a wide arc across the sky during summer. This means that east, south, and west-facing roofs all receive substantial sunlight. The differences in output are meaningful but not dramatic, and the financial case for solar remains strong regardless of your roof's orientation."},{type:"callout",variant:"stat",title:"Output by Orientation",body:"A south-facing roof produces 100% of its rated capacity. East-facing roofs achieve 80–85%, west-facing roofs also achieve 80–85%, and north-facing roofs generate approximately 50–55% of rated capacity."},{type:"heading",level:2,text:"South-Facing Roofs: The Gold Standard"},{type:"paragraph",text:"A south-facing roof is undeniably the optimal orientation for solar panels in Ireland. Because Ireland is in the Northern Hemisphere, the sun arcs from east to west through the southern half of the sky. A south-facing roof therefore receives the most direct sunlight throughout the day, particularly during the peak generation hours of late morning to early afternoon."},{type:"bulletList",items:["Annual output: 100% of rated system capacity","Peak generation: 11am – 3pm (when the sun is highest in the sky)","Best suited for: Households that are home during the day and can use electricity during peak generation hours","Payback period: 5–6 years (fastest of all orientations)"]},{type:"heading",level:2,text:"East-Facing Roofs: The Morning Champions"},{type:"paragraph",text:"East-facing roofs receive their strongest sunlight in the morning, from sunrise through to late morning. While they produce 15–20% less electricity overall than a south-facing roof, they have a unique advantage: their generation profile aligns perfectly with morning household routines."},{type:"paragraph",text:"Think about your morning routine: toast, kettle, shower, lights, phone charging, heating the house. An east-facing system peaks just when you are using the most electricity, meaning more of your solar generation is consumed directly rather than exported to the grid. Since using your own solar electricity is worth more than exporting it (you save €0.35–€0.45/kWh versus earning €0.21/kWh), this higher self-consumption rate partially offsets the lower total output."},{type:"bulletList",items:["Annual output: 80–85% of rated capacity","Peak generation: 8am – 12pm","Best suited for: Households with high morning electricity consumption","Payback period: 6–7 years"]},{type:"heading",level:2,text:"West-Facing Roofs: The Afternoon Powerhouse"},{type:"paragraph",text:"West-facing roofs mirror east-facing ones, with peak generation occurring from mid-afternoon through to early evening. This makes them an excellent choice for households where people are out during the day and return in the late afternoon and evening."},{type:"paragraph",text:"In Ireland, many households follow a pattern where the house is largely empty during the day (people at work or school), and electricity usage peaks in the evening. A west-facing system generates maximum power exactly when you come home and start cooking, running appliances, and turning on lights. Like east-facing systems, this high self-consumption rate means the financial returns are better than the raw output figures suggest."},{type:"bulletList",items:["Annual output: 80–85% of rated capacity","Peak generation: 2pm – 6pm","Best suited for: Households that are out during the day and home in the evening","Payback period: 6–7 years"]},{type:"heading",level:2,text:"North-Facing Roofs: Worth It?"},{type:"paragraph",text:"North-facing roofs receive the least direct sunlight in Ireland. A north-facing solar array will typically generate only 50–55% of a south-facing equivalent. For most homeowners, this is not an attractive proposition — the longer payback period (9–11 years) means the financial returns are significantly diminished."},{type:"paragraph",text:"However, there are exceptions. If you have a large roof area and can fit a bigger system on the north side for a low additional cost, or if your north roof is completely free from shading while your south roof is obstructed, a north-facing installation can still make financial sense. Some installers also offer mixed-orientation setups."},{type:"heading",level:2,text:"Split Arrays: The Best of Both Worlds"},{type:"paragraph",text:"If your home has roof planes facing different directions, you may be able to install a split array — panels on both an east and a west roof, for example. Split arrays have become increasingly popular in Ireland because they offer a broader generation profile throughout the day."},{type:"table",headers:["Configuration","Annual Output","Generation Pattern","Best For"],rows:[["South only","100%","Midday peak","Daytime home workers"],["East + West split","85–90%","Broad morning–evening curve","Families out during the day"],["East + South split","90–95%","Morning–midday curve","Shift workers, high morning use"],["South + West split","90–95%","Midday–evening curve","Afternoon/evening households"]]},{type:"callout",variant:"tip",title:"Split Array Advantage",body:"A split east/west array generates less total electricity than a south-facing equivalent, but it typically has a much higher self-consumption rate (up to 70–80% vs 40–50% for south-only). This means less electricity is exported at the lower CEG rate and more is consumed at the full electricity price — improving your overall financial return."},{type:"heading",level:2,text:"Other Factors That Matter More Than Orientation"},{type:"paragraph",text:"While roof orientation is important, several other factors have an equal or greater impact on your system's performance:"},{type:"bulletList",items:["Shading — Even a small amount of shading (chimney, tree, neighbouring building) can reduce output by 10–25%. Eliminating shading is more important than optimising orientation.","Pitch angle — The ideal pitch for Ireland is approximately 35–40°. Most standard Irish roofs fall within 30–45°, which is excellent for solar.","Roof condition — A roof that needs replacement within the next 5–10 years should be replaced before installing solar. Removing and reinstalling panels adds significant cost.","System sizing — An oversized system on a west-facing roof may produce more usable energy than an undersized system on a south-facing roof."]},{type:"paragraph",text:"The key takeaway is simple: if your roof faces east, south, or west, solar panels are a worthwhile investment in Ireland. The differences between these orientations are relatively modest in the context of a 25-year panel lifespan, and the financial case remains strong across all three."},{type:"divider"},{type:"cta",text:"Get a Free Roof Assessment for Your Home",href:"/#calculator"}]},{slug:"battery-storage-is-it-worth-the-extra-cost",title:"Battery Storage: Is It Worth the Extra Cost?",image:"/blog-battery-storage.webp",excerpt:"Solar batteries cost €4,000-€8,000 — but can they pay for themselves? We break down the maths with real Irish energy prices and usage patterns to help you decide.",category:"savings",date:"22 Mar 2026",readTime:"10 min read",author:"Cal O'Reilly",iconBg:"bg-emerald-400/10",iconColor:"text-emerald-400",content:[{type:"heading",level:2,text:"The Battery Storage Question"},{type:"paragraph",text:"Adding battery storage to your solar panel system is the single biggest decision you will make after choosing to go solar. It is also the most expensive optional component, with prices ranging from €4,000 to €8,000 depending on capacity, brand, and installation complexity. So, is it worth the extra cost? The honest answer is: it depends on your circumstances."},{type:"paragraph",text:"This guide will walk you through the financial maths, the practical benefits, and the specific scenarios where a battery delivers genuine value. We will not sugarcoat it — for some households, a battery is an excellent investment. For others, it is money better spent on a larger solar array or kept in the bank. Our goal is to help you figure out which camp you fall into."},{type:"callout",variant:"stat",title:"Battery Market in Ireland",body:"Approximately 35% of new solar installations in Ireland now include battery storage, up from just 10% in 2022. Note: The previous €600 SEAI battery grant was discontinued — there is no standalone battery grant in 2026, making the ROI calculation more important than ever."},{type:"heading",level:2,text:"How Much Do Solar Batteries Cost?"},{type:"paragraph",text:"Solar battery prices have fallen significantly over the past five years, driven by advances in lithium iron phosphate (LFP) technology and increased global manufacturing capacity. Here is a breakdown of current battery costs in Ireland for 2026:"},{type:"callout",variant:"warning",title:"Battery Grant Discontinued",body:"The previous €600 SEAI battery storage grant has been discontinued. There is no standalone grant for batteries in 2026, which means the full cost of battery storage falls to you. Factor this into your payback calculations — most batteries now take 8–12 years to pay for themselves through savings alone."},{type:"table",headers:["Battery Capacity","Typical Cost","Best For"],rows:[["3–5 kWh (small)","€4,000 – €5,500","Small households, low evening usage"],["5–7 kWh (medium)","€5,000 – €7,000","Average 3-4 person household"],["7–10 kWh (large)","€6,500 – €8,000","Large homes, EV owners, high usage"],["10–13.5 kWh (XL)","€8,000 – €10,000","Off-grid capability, heat pumps"]]},{type:"paragraph",text:"The most popular battery size for Irish households is 5–7 kWh, which provides enough storage to cover typical evening electricity consumption (6pm–11pm). The Tesla Powerwall 2 (13.5 kWh) is the most well-known option but is also the most expensive — for most Irish homes, a 5–7 kWh battery from a brand like Huawei, BYD, or Pylontech offers better value."},{type:"heading",level:2,text:"Payback Calculations: Does a Battery Pay for Itself?"},{type:"paragraph",text:"The payback period for a solar battery is longer than for panels alone. While solar panels typically pay for themselves in 5–7 years, a battery usually takes 8–12 years. However, this varies dramatically based on your electricity usage patterns. Let us look at the numbers:"},{type:"paragraph",text:"Without a battery, a typical 6kWp solar system generates approximately 5,000 kWh per year. If you use 50% directly and export 50%, your annual savings look like this: €875 in direct savings (2,500 kWh × €0.35/kWh) plus €263 in CEG earnings (2,500 kWh × €0.105 effective rate). Total: approximately €1,138 per year."},{type:"paragraph",text:"With a 5 kWh battery, you can increase your self-consumption to approximately 75–80%. That means consuming 4,000 kWh directly and exporting only 1,000 kWh: €1,400 in direct savings (4,000 kWh × €0.35/kWh) plus €105 in CEG earnings (1,000 kWh × €0.105 effective rate). Total: approximately €1,505 per year."},{type:"table",headers:["Scenario","Annual Savings","Battery Cost (Net)","Payback Period"],rows:[["No battery","€1,138","N/A","N/A"],["5 kWh battery + solar","€1,505","€5,400","~9.3 years"],["7 kWh battery + solar","€1,575","€6,400","~10.8 years"],["10 kWh battery + solar","€1,645","€7,400","~12.1 years"]]},{type:"callout",variant:"info",title:"Understanding the Numbers",body:"A battery saves you money by reducing your grid imports during the evening and night. The value of each stored kWh is €0.35–€0.45 (the price you would otherwise pay for grid electricity), versus the €0.21 you earn from exporting it. Storing your own solar is worth nearly double what exporting it earns."},{type:"heading",level:2,text:"When a Battery Makes Sense"},{type:"paragraph",text:"There are several specific scenarios where adding a battery is a genuinely smart financial decision:"},{type:"bulletList",items:["You have an electric vehicle — An EV adds 3,000–5,000 kWh to your annual electricity consumption. A battery lets you charge your EV from stored solar power overnight, dramatically reducing your motoring costs.","You are on a time-of-use tariff — If your electricity supplier charges more during peak hours (5pm–7pm) and less at night, a battery lets you avoid peak rates entirely by using stored solar during expensive periods.","You have a heat pump — Heat pumps use significant electricity, particularly in winter. A battery can supplement your heat pump's power needs during peak pricing periods.","You work from home — If you are home during the day, you may not export much excess solar. But if your solar output exceeds your daytime needs (large system), a battery captures the surplus for the evening.","You want backup power — If power cuts are a concern in your area, most solar batteries can provide backup power during outages (though this usually requires an additional configuration and switchgear)."]},{type:"heading",level:2,text:"When a Battery Does NOT Make Sense"},{type:"paragraph",text:"Be honest with yourself — a battery is not right for everyone. Here are the scenarios where we would advise against adding one:"},{type:"bulletList",items:["Your budget is tight — If you are stretching your finances to afford solar panels, do not add a battery on top. Panels alone deliver an excellent return, and you can always add a battery later.","You are home all day — If someone is home during daylight hours, you likely consume 60–70% of your solar generation directly. The marginal benefit of a battery is smaller when self-consumption is already high.","You have a small system — A 4kWp system generates relatively little surplus. A battery may spend much of its time empty or only partially charged, reducing its value.","Your roof faces east or west — Split orientation systems already have broad generation profiles, and the surplus available for storage is smaller than a south-facing system."]},{type:"heading",level:2,text:"Battery Sizing Guide"},{type:"paragraph",text:"Choosing the right battery size is crucial. Too small, and it will not store enough to make a meaningful difference. Too large, and you will never fill it, wasting money on unused capacity. As a general rule, your battery capacity should be between 1 and 1.5 times your daily solar surplus."},{type:"table",headers:["Household Size","Daily Usage (kWh)","Solar System","Recommended Battery"],rows:[["1–2 people","10–15 kWh","4kWp","3–5 kWh"],["3–4 people","15–25 kWh","6kWp","5–7 kWh"],["5+ people","25–35+ kWh","8–10kWp","7–10 kWh"],["EV owner (any)","+10–15 kWh","6–10kWp","10–13.5 kWh"]]},{type:"callout",variant:"tip",title:"Future-Proof Tip",body:"Most lithium iron phosphate batteries can be expanded by adding additional modules later. You do not have to buy your full capacity upfront. Start with a smaller battery and add capacity as your needs grow (e.g., when you buy an EV)."},{type:"paragraph",text:"Ultimately, the decision to add battery storage comes down to your personal circumstances, budget, and electricity usage patterns. For many Irish households, especially those with EVs or on time-of-use tariffs, a battery is a worthwhile addition that accelerates long-term savings. For others, investing in more panels or simply saving the money is the smarter choice."},{type:"divider"},{type:"cta",text:"Get a Custom Battery + Solar Recommendation",href:"/#calculator"}]},{slug:"planning-permission-solar-panels-ireland",title:"Planning Permission for Solar Panels in Ireland — What You Need to Know",image:"/blog-solar-installation.webp",excerpt:"Good news — most domestic solar installations in Ireland don't need planning permission. Here are the exceptions, limits, and guidelines you should be aware of before installing.",category:"guides",date:"18 Mar 2026",readTime:"5 min read",author:"Cal O'Reilly",iconBg:"bg-rose-400/10",iconColor:"text-rose-400",content:[{type:"heading",level:2,text:"The Good News: Exempted Development"},{type:"paragraph",text:'If you are considering installing solar panels on your home in Ireland, here is the best news you will hear: the vast majority of domestic solar installations do not require planning permission. Under Irish planning law, solar panels on residential properties fall under "exempted development," which means you can proceed without applying to your local county council.'},{type:"paragraph",text:"This exemption was introduced to remove barriers to renewable energy adoption and has been instrumental in the rapid growth of residential solar across Ireland. However, the exemption is not unlimited — there are specific conditions you must adhere to. Exceeding these limits means you will need to go through the full planning permission process, which can add months and significant cost to your project."},{type:"callout",variant:"tip",title:"Quick Answer",body:"If you are installing solar panels on a typical Irish home that is not a protected structure and is not in a conservation area, you almost certainly do not need planning permission. Your installer will confirm this during the initial survey."},{type:"heading",level:2,text:"Exempted Development Limits"},{type:"paragraph",text:"To qualify for exempted development status, your solar installation must comply with the following conditions set out under the Planning and Development Regulations:"},{type:"bulletList",items:["The total area of solar panels on the roof must not exceed 12 square metres (this is measured as the total footprint of all panels combined)","No solar panel should extend more than 50 centimetres above the existing roof surface (measured from the highest point of the roof tiles/slates to the top of the panel)","The solar panels must be installed on the roof — not on walls, fences, or freestanding structures (ground-mounted solar requires separate planning)","The installation must be on a house or apartment building — not on a shed, garage, or outbuilding (with limited exceptions)","Panels should not project beyond the external wall of the building at any point"]},{type:"callout",variant:"info",title:"12 Square Metres Explained",body:"Twelve square metres is approximately 8–10 standard solar panels (depending on panel size). This is enough for a 4–5kWp system, which is sufficient for most smaller Irish households. For larger systems (6kWp+), you may need to split panels across multiple roof planes or apply for planning permission if you want them all on one roof."},{type:"heading",level:2,text:"When You DO Need Planning Permission"},{type:"paragraph",text:"There are specific situations where planning permission is required for solar panels in Ireland. It is important to identify these before you commit to an installation:"},{type:"bulletList",items:["Protected structures — If your home is a protected structure or a proposed protected structure, you will need planning permission for any external alteration, including solar panels. This includes Georgian, Victorian, and Edwardian buildings in certain areas.","Architectural conservation areas (ACAs) — If your property is located within a designated ACA, special rules apply. Some ACAs restrict solar panel installations that are visible from the street.","Exceeding the 12m² limit — If you want a larger system that exceeds 12 square metres of roof-mounted panels, you will need planning permission.","Flat roof installations — Panels on flat roofs that project above the parapet wall may require planning permission, depending on the height of the parapet.","Listed buildings — Similar to protected structures, buildings on the National Inventory of Architectural Heritage require planning permission.","Ground-mounted solar — Any freestanding solar panel array on the ground (even in your garden) requires planning permission, regardless of size."]},{type:"callout",variant:"warning",title:"Do Not Risk It",body:"Installing solar panels without planning permission when it is required is an unauthorised development. Your local council can issue an enforcement notice requiring you to remove the panels. Always check with your installer and, if in doubt, contact your local planning department before proceeding."},{type:"heading",level:2,text:"Protected Structures and Heritage Homes"},{type:"paragraph",text:"If you own a protected structure, you can still install solar panels — but you will need to go through the planning permission process. This involves submitting detailed plans showing how the panels will be installed and demonstrating that they will not materially alter the character of the building."},{type:"paragraph",text:"Tips for protected structure owners include: choosing dark-framed panels that blend with dark roof tiles, positioning panels on rear roof slopes that are not visible from the street, considering in-roof systems where panels replace roof tiles rather than sitting on top of them, and working with an installer experienced in heritage projects."},{type:"heading",level:2,text:"BER Assessment Exemption"},{type:"paragraph",text:"While not directly related to planning permission, it is worth noting that having solar panels does not automatically trigger a BER assessment requirement. However, if you are applying for the SEAI grant, you will need a BER assessment as part of the grant conditions. This is separate from planning permission and is managed through the SEAI portal rather than your local council."},{type:"heading",level:2,text:"Summary: Do You Need Planning?"},{type:"table",headers:["Scenario","Planning Required?","Notes"],rows:[["Standard house, <12m² of panels","No","Exempted development applies"],["Standard house, >12m² of panels","Yes","Apply through local council"],["Protected structure","Yes","Heritage impact assessment required"],["In an ACA","Maybe","Check with local planning department"],["Flat roof (below parapet)","No","Exempted if not visible above parapet"],["Flat roof (above parapet)","Maybe","Depends on height and visibility"],["Ground-mounted panels","Yes","Always requires planning permission"],["Apartment block (own apartment only)","No","Exempted for individual units"]]},{type:"paragraph",text:"The vast majority of Irish homeowners will never need to worry about planning permission for their solar installation. The exempted development rules are generous enough to accommodate most standard residential setups. If you have any doubts, your SEAI-registered installer will be able to advise you during the initial consultation and survey."},{type:"divider"},{type:"cta",text:"Book a Free Survey — We Will Check Planning for You",href:"/#calculator"}]},{slug:"longi-vs-jinko-vs-trina-best-solar-panels",title:"LONGi vs Jinko vs Trina: Which Solar Panels Are Best for Irish Homes?",image:"/blog-solar-installation.webp",excerpt:"We compare the top three tier-1 solar panel brands used in Ireland — efficiency, warranties, real-world performance, and which one delivers the best value for your home.",category:"technology",date:"12 Mar 2026",readTime:"8 min read",author:"Cal O'Reilly",iconBg:"bg-sky-400/10",iconColor:"text-sky-400",content:[{type:"heading",level:2,text:"The Big Three: LONGi, Jinko, and Trina"},{type:"paragraph",text:"When it comes to choosing solar panels for your Irish home, three manufacturers dominate the market: LONGi, Jinko Solar, and Trina Solar. All three are Chinese Tier-1 manufacturers with global reputations for quality, reliability, and innovation. Between them, they account for an estimated 70–80% of all residential solar panels installed in Ireland."},{type:"paragraph",text:"But which one is right for you? While all three produce excellent panels, there are meaningful differences in efficiency, degradation rates, warranty terms, real-world performance in Irish weather conditions, and price. This guide provides an honest, side-by-side comparison to help you make an informed decision."},{type:"callout",variant:"info",title:"What Is a Tier-1 Panel?",body:"Tier-1 is a classification by Bloomberg New Energy Finance (BNEF) that indicates a manufacturer is vertically integrated, financially stable, and has a proven track record. It is the solar industry's gold standard for bankability and reliability."},{type:"heading",level:2,text:"LONGi Hi-MO 6: The Efficiency Leader"},{type:"paragraph",text:"LONGi is the world's largest manufacturer of monocrystalline silicon solar panels and is widely regarded as the industry leader in panel efficiency. Their Hi-MO 6 series, launched in 2023 and updated for 2026, represents the cutting edge of residential solar technology."},{type:"bulletList",items:["Efficiency: 22.3–22.8% (highest of the three)","Cell type: Monocrystalline PERC with HPDC technology","Power output: 410–440W per panel (standard 60-cell format)","Temperature coefficient: -0.29%/°C (excellent for Irish climate)","Degradation: 0.55% per year in year 1, then 0.4% per year","Warranty: 25-year product warranty, 30-year performance warranty (87.4% output at year 30)"]},{type:"paragraph",text:"LONGi panels are particularly well-suited to Ireland because of their excellent low-light performance and temperature coefficient. Ireland's mild climate means panels rarely overheat, and LONGi's low temperature coefficient means they lose less efficiency in warm conditions. They also perform exceptionally well in diffuse light conditions (cloudy days), which accounts for much of Ireland's annual solar resource."},{type:"heading",level:2,text:"Jinko Tiger Neo: The Value Pick"},{type:"paragraph",text:"Jinko Solar is the world's largest shipper of solar modules and has a particularly strong presence in the Irish residential market. Their Tiger Neo series uses N-type TOPCon cell technology, which represents the next generation of solar cell architecture beyond PERC."},{type:"bulletList",items:["Efficiency: 21.8–22.5%","Cell type: N-type TOPCon (tunnel oxide passivated contact)","Power output: 400–430W per panel","Temperature coefficient: -0.30%/°C","Degradation: 1% in year 1, then 0.4% per year (N-type advantage)","Warranty: 25-year product warranty, 30-year performance warranty (87.4% output at year 30)"]},{type:"paragraph",text:"The key advantage of Jinko's Tiger Neo is its N-type TOPCon technology. N-type cells are less prone to light-induced degradation (LID) than the P-type cells used in older panel designs. This means Jinko panels retain their output better over the first few years of operation. In practical terms, a Jinko Tiger Neo panel may produce 1–2% more electricity in year 5 compared to a similar P-type panel, as P-type panels degrade faster in their early years."},{type:"heading",level:2,text:"Trina Vertex S+: The All-Rounder"},{type:"paragraph",text:"Trina Solar is one of the industry's most established players, having been founded in 1997. Their Vertex S+ series for residential applications offers a well-balanced combination of performance, reliability, and value."},{type:"bulletList",items:["Efficiency: 21.5–22.3%","Cell type: Monocrystalline PERC with multi-busbar technology","Power output: 390–425W per panel","Temperature coefficient: -0.30%/°C","Degradation: 1% in year 1, then 0.4% per year","Warranty: 25-year product warranty, 25-year performance warranty (84.8% output at year 25)"]},{type:"paragraph",text:"Trina's Vertex S+ is a solid, reliable workhorse. While it does not lead on any single metric, it offers consistently good performance across the board. Trina panels are also among the most widely available in Ireland, which can mean shorter lead times and competitive pricing from installers."},{type:"heading",level:2,text:"Head-to-Head Comparison"},{type:"table",headers:["Feature","LONGi Hi-MO 6","Jinko Tiger Neo","Trina Vertex S+"],rows:[["Panel Efficiency","22.3–22.8%","21.8–22.5%","21.5–22.3%"],["Power Output","410–440W","400–430W","390–425W"],["Temp Coefficient","-0.29%/°C","-0.30%/°C","-0.30%/°C"],["Year 1 Degradation","0.55%","1.0%","1.0%"],["Annual Degradation","0.40%","0.40%","0.40%"],["Product Warranty","25 years","25 years","25 years"],["Performance Warranty","30 years (87.4%)","30 years (87.4%)","25 years (84.8%)"],["Typical Price (per panel)","€180–€220","€160–€200","€150–€190"],["Irish Suitability","★★★★★","★★★★☆","★★★★☆"],["Value for Money","★★★★☆","★★★★★","★★★★★"]]},{type:"heading",level:2,text:"Performance in Irish Weather"},{type:"paragraph",text:"Ireland's climate presents specific challenges for solar panels: frequent cloud cover, relatively mild temperatures, high humidity, and occasional salt spray in coastal areas. All three brands handle these conditions well, but there are subtle differences worth noting."},{type:"paragraph",text:"LONGi's slight edge in efficiency and temperature coefficient makes it marginally better in Irish conditions, particularly during the summer months when temperatures can occasionally rise above 25°C. However, the difference in real-world annual output between LONGi and Jinko panels of the same wattage is typically less than 2–3% — which translates to roughly 20–40 kWh per year on a standard 6kWp system. This is not a decisive difference for most homeowners."},{type:"paragraph",text:"All three brands use anodised aluminium frames and tempered glass that meet the IEC 61215 standard for durability. They are all rated to withstand wind speeds of 2,400 Pa (approximately 150 km/h) and snow loads of 5,400 Pa — more than sufficient for Irish weather conditions."},{type:"heading",level:2,text:"Our Recommendation"},{type:"paragraph",text:"For most Irish homeowners, the choice between these three panels comes down to price and availability rather than performance. All three will serve you well for 25+ years. Here is our simple recommendation:"},{type:"bulletList",items:["If your roof space is limited — choose LONGi Hi-MO 6 for maximum output per square metre","If you want the best value — choose Jinko Tiger Neo, which offers N-type technology at competitive prices","If your installer strongly recommends Trina — go with it, the Vertex S+ is a proven performer and availability can matter","Do not stress too much about the brand — panel quality matters, but installer quality matters more. A well-installed Trina system will outperform a poorly installed LONGi system every time"]},{type:"callout",variant:"tip",title:"The Real Secret",body:"The most important factor in your solar system's long-term performance is not the panel brand — it is the quality of the installation. A skilled installer who takes care with wiring, inverter placement, shading analysis, and roof attachment will deliver better results than a premium panel installed poorly. Choose your installer as carefully as you choose your panels."},{type:"divider"},{type:"cta",text:"Get a Quote with Premium Panel Options",href:"/#calculator"}]},{slug:"solar-panels-dublin-ultimate-guide",title:"Solar Panels in Dublin: The Ultimate 2026 Guide",image:"/blog-county-cork.webp",excerpt:"Everything Dublin homeowners need to know about going solar — from grant eligibility and installation costs to the best panels for Dublin's weather and typical roof types.",category:"county",date:"6 Mar 2026",readTime:"11 min read",author:"Cal O'Reilly",iconBg:"bg-orange-400/10",iconColor:"text-orange-400",content:[{type:"heading",level:2,text:"Why Dublin Is Leading Ireland's Solar Revolution"},{type:"paragraph",text:"Dublin is at the forefront of Ireland's residential solar energy boom. With approximately 550,000 residential properties, the capital has the highest concentration of potential solar installations in the country. In 2025 alone, an estimated 12,000 Dublin homes installed solar panels — more than any other county — and this figure is expected to grow by 25% in 2026."},{type:"paragraph",text:"Several factors make Dublin uniquely positioned for solar adoption: high electricity prices (among the highest in the country due to urban network charges), a large number of suitable roof types, excellent installer availability, and a dense population of environmentally conscious homeowners. Dublin City Council has also been proactive in streamlining the process for solar installations, and the county has some of the highest smart meter penetration rates in Ireland."},{type:"callout",variant:"stat",title:"Dublin Solar Stats",body:"Over 35,000 Dublin homes now have solar panels installed. The average 6kWp system in Dublin generates approximately 5,000–5,500 kWh per year, saving homeowners €900–€1,200 annually on electricity bills."},{type:"heading",level:2,text:"Solar Panel Costs in Dublin (2026)"},{type:"paragraph",text:"Solar panel installation costs in Dublin are slightly higher than the national average, primarily due to higher labour costs, parking charges for installation crews, and the logistical challenges of working in a densely populated urban area. However, the increased competition among Dublin-based installers has kept prices competitive."},{type:"table",headers:["System Size","Dublin Cost Range","National Average","After Grant"],rows:[["4kWp (10–12 panels)","€6,500 – €8,500","€6,000 – €8,000","€4,700 – €6,700"],["6kWp (14–16 panels)","€9,000 – €12,000","€8,500 – €11,000","€7,200 – €10,200"],["10kWp (22–26 panels)","€13,000 – €17,000","€12,000 – €16,000","€11,200 – €15,200"]]},{type:"paragraph",text:"Dublin costs are typically 5–10% above the national average, but the higher electricity prices in Dublin mean the financial returns are actually slightly better. At an average urban electricity rate of €0.40/kWh (including standing charges and VAT), a 6kWp system in Dublin pays for itself in approximately 5.5–6.5 years — slightly faster than the national average of 6–7 years."},{type:"heading",level:2,text:"Dublin Roof Types and Solar Compatibility"},{type:"paragraph",text:"Dublin has a diverse range of housing stock, from Georgian townhouses to modern estates. Each roof type presents unique opportunities and challenges for solar installation:"},{type:"heading",level:3,text:"Victorian and Edwardian Terraces (1890–1920)"},{type:"paragraph",text:"These are found throughout Dublin 4, Dublin 6, Rathmines, Ranelagh, and Drumcondra. They typically have steeply pitched slate roofs with multiple chimney stacks. Solar compatibility is generally good — the roof pitch (35–45°) is ideal, and many have south-facing rear roof slopes. The main challenges are narrow terraces where scaffolding access can be difficult, chimneys that cause shading, and fragile original slate roofs that may need reinforcement before panel installation."},{type:"heading",level:3,text:"1930s–1950s Suburban Semis"},{type:"paragraph",text:'Common in areas like Templeogue, Donnybrook, Milltown, and Drumcondra. These homes typically have pitched tiled roofs with generous ridge-to-eave measurements. They are among the easiest roof types for solar installation — ample space, standard pitches, and minimal shading. Many have both front and rear roof slopes, allowing for split east/west arrays. This is the "sweet spot" roof type for solar in Dublin.'},{type:"heading",level:3,text:"1960s–1980s Bungalows"},{type:"paragraph",text:"Found in suburban areas like Tallaght, Clondalkin, Ballymun, and Blanchardstown. These single-storey homes often have shallow-pitched roofs (15–25°) with large unshaded areas. The shallow pitch is suboptimal for solar (ideal is 35–40°), but the large roof area compensates — you can often fit more panels than on a standard two-storey house. Scaffolding is cheaper (single storey), which reduces installation costs."},{type:"heading",level:3,text:"Modern Estates (2000–present)"},{type:"paragraph",text:"Found in areas like Swords, Lucan, Leopardstown, and Adamstown. Modern homes typically have concrete tile roofs with standard pitches (30–35°) and clean rooflines. They are excellent for solar — minimal shading, strong roof structures, and many are already pre-wired for solar conduit. Some newer developments in Dublin even include solar panels as standard."},{type:"callout",variant:"tip",title:"Dublin Roof Tip",body:"If you live in a Dublin terrace, ask your installer about a split east/west array on your front and rear roof slopes. This maximises generation throughout the day without requiring scaffolding around the sides of the building (which can require neighbour permission)."},{type:"heading",level:2,text:"Grant Uptake and Statistics in Dublin"},{type:"paragraph",text:"Dublin has consistently led the country in SEAI grant applications for solar panels. The county accounts for approximately 25% of all national solar grant applications, despite having only about 15% of the national housing stock. This reflects the higher energy costs in Dublin, greater environmental awareness, and easier access to SEAI-registered installers."},{type:"table",headers:["Dublin Metric","Figure"],rows:[["Total SEAI solar grants issued (to date)","~35,000"],["Average grant application processing time","4–5 weeks"],["Homes with solar panels","~8% of residential properties"],["Average system size installed","5.8 kWp"],["Most popular panel brand","Jinko Solar (Tiger Neo)"],["Average installation time","1–2 days"]]},{type:"heading",level:2,text:"Choosing an Installer in Dublin"},{type:"paragraph",text:"Dublin has the highest concentration of solar installers in Ireland, which is both a blessing and a challenge. More choice means better pricing, but it also means more research is needed to find a quality installer. Here are our tips for Dublin homeowners:"},{type:"numberedList",items:["Always use an SEAI-registered installer — verify registration on seai.ie before signing any contract","Get at least 3 quotes — Dublin installer prices can vary by 20–30% for identical systems","Check reviews on Google and Trustpilot — pay particular attention to reviews from Dublin homeowners, as installation quality can vary by area","Ask about scaffolding costs — Dublin parking and access can add €200–€500 to scaffolding costs. Some quotes include this, others do not","Check for Dublin-specific experience — installers who regularly work in Dublin's older housing stock will be better equipped to handle fragile slate roofs and tight terrace access","Ask about the ECS registration process — your installer should handle ESB Networks registration and smart meter coordination","Verify warranty coverage — ensure your installer provides a workmanship warranty of at least 5 years on top of the manufacturer's panel warranty"]},{type:"heading",level:2,text:"Dublin Council Areas and Considerations"},{type:"paragraph",text:"Dublin is divided into four local authority areas: Dublin City Council, South Dublin County Council, Fingal County Council, and Dún Laoghaire-Rathdown County Council. While the planning rules are consistent across all four (following national exempted development guidelines), there are some local nuances to be aware of:"},{type:"bulletList",items:["Dublin City Council — High density of protected structures and ACAs. If your home is in areas like Georgian Dublin (Mountjoy Square, Merrion Square), St. Stephen's Green, or the Liberties, check for heritage designations before proceeding.","Dún Laoghaire-Rathdown — Several scenic conservation areas along the coast. Seafront properties in Dalkey, Killiney, and Sandycove may have additional restrictions on roof alterations visible from the sea.","South Dublin County Council — Relatively few heritage restrictions. Suburban areas like Tallaght, Clondalkin, and Lucan are straightforward for solar installation.","Fingal County Council — Mix of suburban and rural. Areas like Swords, Malahide, and Howth have good solar potential. Rural properties in north County Dublin may be able to accommodate larger systems."]},{type:"heading",level:2,text:"Solar Generation in Dublin vs Rest of Ireland"},{type:"paragraph",text:"Dublin's solar resource is comparable to the rest of Ireland, with a slight advantage in coastal areas due to less cloud cover compared to inland counties. A typical 6kWp system in Dublin will generate approximately 5,000–5,500 kWh per year, depending on roof orientation, pitch, and shading. This is slightly above the national average, partly due to Dublin's coastal location benefiting from clearer coastal skies."},{type:"paragraph",text:"The urban heat island effect also provides a marginal benefit. Dublin city centre is typically 1–2°C warmer than surrounding rural areas, which can slightly increase panel efficiency during cooler months (though excessive heat in summer is counterproductive, the Irish climate rarely gets warm enough for this to be a concern)."},{type:"callout",variant:"info",title:"Dublin vs National Comparison",body:"Dublin homes pay approximately 5–10% more for electricity than the national average (due to urban network charges), but also save 5–10% more with solar. The net financial advantage of going solar in Dublin is slightly better than in most other Irish counties."},{type:"heading",level:2,text:"Getting Started: Your Next Steps"},{type:"paragraph",text:"If you are a Dublin homeowner considering solar panels, here is a simple roadmap to get started:"},{type:"numberedList",items:["Check your eligibility — Use our free solar calculator to get an instant estimate of your potential savings and system size. You will need your ESB MPRN number and recent electricity bills.","Get multiple quotes — Contact at least 3 SEAI-registered installers operating in your area. Compare not just prices, but panel brands, inverter options, warranties, and aftercare.","Verify your roof — Your chosen installer will conduct a free survey (usually using satellite imagery and sometimes a physical site visit) to confirm your roof is suitable and identify any potential issues.","Apply for the grant — Once you have chosen your installer, apply for the SEAI grant online. Your installer can usually assist with this process.","Schedule installation — Most Dublin installations can be completed within 4–8 weeks of grant approval, subject to installer availability and weather conditions.","Register for CEG — After installation, ensure your energy supplier is notified so you can start earning from your excess solar export."]},{type:"paragraph",text:"Dublin is an excellent place to go solar. The combination of high electricity prices, a competitive installer market, diverse and largely suitable roof types, and strong grant uptake means that Dublin homeowners are among the best-placed in Ireland to benefit from solar energy. With a payback period of just 5.5–6.5 years and 25+ years of free electricity ahead, there has never been a better time to make the switch."},{type:"divider"},{type:"cta",text:"Get a Free Dublin Solar Quote — See Your Savings",href:"/#calculator"}]},{slug:"seai-grant-stay-e1800-2026-what-it-means",title:"SEAI Grant Stays at €1,800 for 2026 — What It Means for You",image:"/blog-solar-financing.webp",excerpt:"The government has confirmed the SEAI solar panel grant will remain at €1,800 for 2026. Here is what the announcement means for homeowners, the grant's history, and why now is still the time to apply.",category:"news",date:"28 Apr 2026",readTime:"5 min read",author:"Cal O'Reilly",iconBg:"bg-violet-400/10",iconColor:"text-violet-400",content:[{type:"heading",level:2,text:"The Announcement"},{type:"paragraph",text:"In November 2025, Minister for Housing, Local Government and Heritage Darragh O'Brien confirmed that the SEAI solar PV grant would remain at €1,800 for the entirety of 2026. This announcement came as a relief to thousands of homeowners who were planning solar installations, as the grant had been on a steady downward trajectory and was widely expected to drop to €1,500 this year."},{type:"paragraph",text:"The decision reflects the government's ongoing commitment to residential renewable energy and its recognition that solar adoption in Ireland is still accelerating. With over 65,000 homes now equipped with solar panels and applications running 40% ahead of 2024 levels, the grant is clearly doing its job — and the government has chosen to maintain the incentive rather than risk slowing momentum."},{type:"callout",variant:"stat",title:"Best Value in the Scheme's History",body:"The €1,800 grant represents the best value in the scheme's history when combined with falling panel prices. Solar system costs have dropped 20–30% since 2021, meaning the grant now covers a larger percentage of total installation costs than ever before."},{type:"heading",level:2,text:"What This Means for Homeowners"},{type:"paragraph",text:"The most immediate impact of this announcement is stability. Homeowners who were considering solar no longer need to rush their applications to beat a deadline. You can take the time to get multiple quotes, carefully evaluate installers, and plan your installation at a pace that suits you — without worrying that the grant will shrink while you are deciding."},{type:"bulletList",items:["No rush to apply — the €1,800 rate is guaranteed for all of 2026, regardless of when you apply during the year","Better planning — with grant certainty, you can take 4–6 weeks to compare installers and get BER assessments done properly","Combined with falling costs — panel prices have dropped significantly, so your out-of-pocket cost is lower than ever","Stack with CEG — the Clean Export Guarantee means you earn €0.21/kWh on top of bill savings, accelerating payback"]},{type:"heading",level:2,text:"Grant History: How We Got Here"},{type:"paragraph",text:"Understanding the trajectory of the SEAI solar grant helps put the current €1,800 figure into context. When the scheme first launched, the grant was set at €2,400 — a very generous level designed to kickstart the residential solar market in Ireland. However, the grant was always intended to decrease over time as installation costs fell and the market matured."},{type:"table",headers:["Year","Grant Amount","Notes"],rows:[["2018–2019","€2,400","Initial launch — highest grant level to drive early adoption"],["2020","€2,400","Maintained despite COVID-19 disruptions"],["2021","€2,100","First reduction of €300; battery grant of €600 also available"],["2022","€1,800","Second reduction; battery grant retained at €600"],["2023","€1,800","Grant stabilised; battery grant discontinued mid-year"],["2024","€1,800","Expected drop to €1,500 was postponed by ministerial decision"],["2025","€1,800","Maintained again as uptake accelerated to record levels"],["2026","€1,800","Confirmed — the longest period of grant stability in the scheme's history"]]},{type:"paragraph",text:"The pattern is clear: the grant was originally designed to decrease by €300 per year until it reached a floor. However, two factors have intervened. First, the cost of solar installations has fallen faster than anticipated, making the grant represent a smaller percentage of total cost even at the same nominal value. Second, the government has recognised the importance of maintaining momentum towards its 2030 climate targets, which require significant growth in domestic solar generation."},{type:"heading",level:2,text:"Why Falling Panel Prices Make This Even Better"},{type:"paragraph",text:"While the headline grant figure of €1,800 is the same as it has been since 2022, the real-world value of that grant has actually increased. Solar panel prices in Ireland have fallen by approximately 20–30% since 2021, driven by manufacturing overcapacity in China, more efficient supply chains, and increased competition among Irish installers."},{type:"paragraph",text:"To put this in perspective: a 6kWp system that cost €14,000 in 2021 now costs approximately €9,500. The €1,800 grant represented 12.8% of the 2021 cost, but it represents nearly 19% of the 2026 cost. Combined with the fact that electricity prices have risen significantly over the same period, the financial case for solar in 2026 is stronger than at any point in the grant's history."},{type:"heading",level:2,text:"What Could Happen in 2027?"},{type:"paragraph",text:"Looking ahead, the outlook for 2027 is less certain. The government has not made any commitments beyond 2026, and several factors could influence the grant level next year:"},{type:"bulletList",items:["Budget pressures — government departments are under pressure to reduce spending across all areas","Scheme maturity — with over 65,000 installations completed, the argument for continued high grant levels weakens","Political changes — a change of government or minister could lead to different priorities","Energy price movements — if electricity prices fall significantly, the case for subsidising solar weakens"]},{type:"paragraph",text:"That said, nobody predicted the grant would still be at €1,800 in 2026, so any predictions about 2027 should be taken with caution. The safest approach is to apply sooner rather than later. If you are considering solar, the current grant level is locked in for this year, and there is no guarantee it will remain at €1,800 beyond December 2026."},{type:"callout",variant:"tip",title:"Our Advice",body:"Don't wait for 2027. The €1,800 grant is confirmed for 2026, electricity prices are high, and panel costs are low. Every month you delay is a month of free electricity you are not generating. Start your solar journey today."},{type:"divider"},{type:"cta",text:"Claim Your €1,800 Grant — Get a Free Solar Quote",href:"/#calculator"}]},{slug:"solar-panels-and-heat-pumps-perfect-partnership",title:"Solar Panels and Heat Pumps: The Perfect Partnership",image:"/blog-solar-installation.webp",excerpt:"Why combining solar PV with a heat pump is the most cost-effective heating solution for Irish homes — with up to €8,300 in combined SEAI grants available.",category:"guides",date:"20 Apr 2026",readTime:"10 min read",author:"Cal O'Reilly",iconBg:"bg-sky-400/10",iconColor:"text-sky-400",content:[{type:"heading",level:2,text:"Why Solar and Heat Pumps Work So Well Together"},{type:"paragraph",text:"If you are serious about reducing your home's energy bills and carbon footprint, combining solar PV panels with an air-source heat pump is the single most impactful upgrade you can make to an Irish home. The two technologies complement each other perfectly: solar panels generate free electricity during the day, and your heat pump uses that electricity to warm your home. The result? Dramatically lower heating costs, reduced dependence on fossil fuels, and a significantly improved BER rating."},{type:"paragraph",text:"The logic is simple. A heat pump replaces your oil boiler, gas boiler, or electric heating system and provides all of your space heating and hot water using electricity. The problem is that heat pumps use a significant amount of electricity — typically 3,000–5,000 kWh per year for an average Irish home. At current electricity prices of €0.35–€0.45/kWh, that translates to €1,050–€2,250 per year just for heating. This is where solar comes in: by generating free electricity during daylight hours, you can offset a substantial portion of your heat pump's running costs."},{type:"callout",variant:"stat",title:"Key Statistic",body:"A typical heat pump uses 4,000 kWh of electricity per year. If your solar system generates 3,500 kWh and covers even 50% of the heat pump's consumption, you could save approximately €840 per year on heating electricity alone."},{type:"heading",level:2,text:"How Heat Pumps Work"},{type:"paragraph",text:"An air-source heat pump works like a refrigerator in reverse. It extracts heat from the outside air — even in temperatures as low as -20°C — and transfers it into your home using a refrigeration cycle. For every 1 kWh of electricity it consumes, a heat pump typically produces 3–4 kWh of heat, giving it a Coefficient of Performance (COP) of 3–4. This makes it 300–400% efficient compared to direct electric heating, and significantly more efficient than oil or gas boilers."},{type:"bulletList",items:["Air-source heat pumps are the most common type for Irish homes — they are cheaper to install than ground-source and do not require digging up your garden","Typical installation cost: €12,000–€18,000 (including all pipework, radiators or underfloor heating modifications)","Lifespan: 15–20 years for the heat pump unit, with periodic servicing required","Suitable for most homes built after 1990 with reasonable insulation levels; older homes may need insulation upgrades first"]},{type:"heading",level:2,text:"Right-Sizing Both Systems"},{type:"paragraph",text:"Getting the most out of a solar-plus-heat-pump system requires careful sizing of both components. The key principle is that your solar system should be sized to generate enough electricity during daylight hours to cover a meaningful portion of your heat pump's consumption, while also meeting your household's general electricity needs."},{type:"paragraph",text:"A typical Irish heat pump draws between 2kW and 4kW when running, depending on the outside temperature and your heating demand. During the heating season (October to March), the heat pump will run for many hours each day. In summer, it mainly provides hot water and runs far less frequently. Here is how the solar-heat pump interaction works across the seasons:"},{type:"table",headers:["Season","Heat Pump Demand","Solar Generation (6kWp)","Solar Coverage"],rows:[["Summer (Jun–Aug)","Low (hot water only)","~1,400 kWh (2.5 months)","80–100% covered"],["Spring/Autumn","Moderate","~1,100 kWh (3 months)","40–60% covered"],["Winter (Dec–Feb)","High","~600 kWh (3 months)","15–25% covered"],["Full Year Average","~4,000 kWh total","~3,500 kWh total","~40–50% covered"]]},{type:"paragraph",text:"As you can see, solar provides excellent coverage in summer when the heat pump barely runs, moderate coverage in spring and autumn, and limited coverage in winter when heating demand peaks. A battery storage system can help bridge the gap by storing excess summer generation for use in the evenings and winter months."},{type:"heading",level:2,text:"SEAI Grants: Up to €8,300 Combined"},{type:"paragraph",text:"One of the most compelling reasons to install both systems together — or even in sequence — is the generous grant support available. The SEAI offers separate grants for heat pumps and solar PV, and they can be combined for a total of up to €8,300 in government funding."},{type:"table",headers:["Grant Component","Amount","Details"],rows:[["Heat Pump Grant (Technology)","€2,000","Flat rate for air-source heat pump installation"],["Heat Pump Grant (Technical)","€2,500","Additional for technical complexity or deeper retrofit"],["Heat Pump Grant (Bonus)","€2,000","Available if your home achieves a BER improvement"],["Solar PV Grant","€1,800","Standard domestic solar PV installation grant"],["Total Possible","Up to €8,300","Combined maximum when all criteria are met"]]},{type:"callout",variant:"tip",title:"Maximise Grant Value",body:"Apply for both grants separately but plan your installations together. Many SEAI-registered installers offer combined solar-plus-heat-pump packages that streamline the process and ensure both systems are optimised to work together from day one."},{type:"heading",level:2,text:"Running Cost Comparison"},{type:"paragraph",text:"To truly appreciate the value of the solar-plus-heat-pump combination, it helps to compare running costs against other heating options. Here is a detailed comparison for a typical Irish home requiring 15,000 kWh of space heating and 3,000 kWh of hot water per year (18,000 kWh total heat demand):"},{type:"table",headers:["Heating System","Fuel Cost/kWh","System Efficiency","Annual Fuel Cost","Annual Electricity Cost"],rows:[["Oil Boiler","€0.10/kWh","85%","€2,120","N/A"],["Gas Boiler (mains)","€0.08/kWh","90%","€1,600","N/A"],["LPG Boiler","€0.12/kWh","85%","€2,540","N/A"],["Direct Electric","€0.40/kWh","100%","N/A","€7,200"],["Heat Pump (alone)","€0.40/kWh","350% (COP 3.5)","N/A","€2,060"],["Heat Pump + Solar","€0.40/kWh","350% (COP 3.5)","N/A","€1,220"]]},{type:"paragraph",text:"The numbers speak for themselves. A heat pump alone cuts heating costs by approximately 50% compared to oil, and by 30% compared to mains gas. Adding solar PV to power the heat pump reduces costs by a further 40%, bringing the total annual heating electricity cost down to approximately €1,220. Compared to an oil boiler costing €2,120 per year, the solar-plus-heat-pump combination saves nearly €900 annually on heating alone — before counting general electricity savings from the solar panels."},{type:"heading",level:2,text:"The Winter Challenge"},{type:"paragraph",text:"The biggest challenge for a solar-plus-heat-pump system is winter. From October through March, your heat pump is working hardest — but your solar panels are generating the least electricity. This creates a seasonal mismatch that can leave you drawing significantly more power from the grid during the months when heating costs are at their highest."},{type:"paragraph",text:"There are several strategies to manage this winter gap:"},{type:"bulletList",items:["Battery storage — A 5–10kWh solar battery can store excess generation from autumn and spring for use during winter evenings. While it will not fully cover the winter heating demand, it can reduce grid dependence by 20–30%.","Time-of-use tariffs — With a smart meter, you can sign up for tariffs that offer cheaper electricity at night. Charge your battery on cheap night-rate power and use it to run the heat pump during peak daytime hours.","CEG credits — Excess solar exported in summer earns you €0.21/kWh, which helps offset your higher winter electricity bills.","Insulation upgrades — Better insulation means your heat pump works less, reducing electricity demand in winter. Consider attic insulation, cavity wall insulation, and window upgrades."]},{type:"heading",level:2,text:"Install Both at Once or One at a Time?"},{type:"paragraph",text:"There is no single right answer — it depends on your budget, your current heating system, and your priorities. Here are the two main approaches:"},{type:"numberedList",items:["Install both simultaneously — This is the most efficient approach. A combined installation means both systems are designed to work together from the start, your installer coordinates everything, and you get both grants in a single process. Total cost (after grants): €12,000–€20,000. Best if your current heating system is old and needs replacement anyway.","Install solar first, add heat pump later — If your current boiler or heating system is still functional, you can install solar panels now and enjoy immediate electricity savings. The SEAI solar grant is guaranteed for 2026. Add the heat pump in a year or two when your current system fails or when you are ready for the investment. Total cost is spread over time, making it easier to manage."]},{type:"paragraph",text:"Whichever approach you choose, the combination of solar PV and a heat pump delivers the lowest long-term energy costs of any heating solution available to Irish homeowners. With combined grants of up to €8,300, BER improvements of 2–3 ratings, and annual energy savings of €1,500–€2,000, it is an investment that pays for itself and then pays you back for decades."},{type:"divider"},{type:"cta",text:"Explore Solar + Heat Pump Packages — Get a Free Assessment",href:"/#calculator"}]},{slug:"smart-meter-required-solar-panels-ireland",title:"Is a Smart Meter Required for Solar Panels in Ireland?",image:"/blog-solar-installation.webp",excerpt:"A smart meter is essential if you want to earn money from your excess solar through the Clean Export Guarantee. Here is how to check if you have one and how to get one installed for free.",category:"guides",date:"14 Apr 2026",readTime:"6 min read",author:"Cal O'Reilly",iconBg:"bg-sky-400/10",iconColor:"text-sky-400",content:[{type:"heading",level:2,text:"The Short Answer: Yes, You Need a Smart Meter"},{type:"paragraph",text:"If you are planning to install solar panels and want to earn money from the electricity you export to the grid through the Clean Export Guarantee (CEG), you absolutely need a smart meter. Without one, your solar installer can still connect your system to the grid, but you will have no way to measure or get paid for the surplus electricity you send back. It is like having a shop but no till — you are giving away your product for free."},{type:"paragraph",text:"A smart meter is a digital electricity meter that replaces your old analogue or digital meter. It measures your electricity consumption and, crucially for solar customers, your electricity generation and export in real time. Unlike old meters, which could only measure the net flow of electricity, a smart meter tracks import and export separately, giving you and your energy supplier an accurate picture of your energy flows."},{type:"callout",variant:"warning",title:"Apply Before Your Solar Installation",body:"Without a smart meter, you cannot register for the Clean Export Guarantee. The installation process for a smart meter typically takes 4–8 weeks, so start this process well before your solar panel installation date. You do not want your panels sitting on your roof, generating free electricity for the grid, while you wait for a meter."},{type:"heading",level:2,text:"ESB Networks Smart Meter Programme"},{type:"paragraph",text:"ESB Networks has been running the National Smart Metering Programme since 2019, with the goal of upgrading every home and small business in Ireland to a smart meter. The programme was originally targeted for completion by the end of 2024, and as of 2026, the vast majority of Irish homes have already been upgraded. However, there are still properties that have not yet received a smart meter, particularly in rural areas or newer housing developments."},{type:"paragraph",text:"The smart meter installation is completely free. ESB Networks covers all costs, including the meter itself and the installation labour. There is no standing charge increase or hidden fee — the smart meter simply replaces your existing meter and operates alongside your current electricity supply arrangement."},{type:"heading",level:2,text:"How to Check if You Already Have a Smart Meter"},{type:"paragraph",text:"Before requesting a smart meter, it is worth checking whether you already have one. Many homeowners do not realise they have been upgraded, as ESB Networks typically does the replacement without a prior appointment. Here are the ways to check:"},{type:"numberedList",items:["Look at your meter — Smart meters have a digital display (sometimes with scrolling text) and typically display your consumption in kWh. They are usually white or grey rectangular boxes, larger than old analogue meters. If your meter has a spinning disc or small dials, it is not a smart meter.","Check your electricity bill — Some suppliers include smart meter data on your bill, showing half-hourly or daily consumption patterns. If your bill includes this level of detail, you likely have a smart meter.",'Check online — Visit the ESB Networks website at esbnetworks.ie and use their "Check My Meter" tool. Enter your MPRN number (found on your electricity bill) to see your meter type.',"Call ESB Networks — Phone 01 698 5005 with your MPRN number and ask if your property has a smart meter installed."]},{type:"heading",level:2,text:"How to Request a Smart Meter"},{type:"paragraph",text:"If you have confirmed that you do not have a smart meter, requesting one is straightforward. The process is as follows:"},{type:"numberedList",items:["Visit esbnetworks.ie/smartmeters and submit a smart meter request form, or call 01 698 5005.","Provide your MPRN number and contact details. ESB Networks will schedule a survey of your meter location.","An ESB Networks contractor will visit your property to assess the meter location and confirm installation requirements. This usually happens within 2–4 weeks of your request.","The smart meter installation itself takes 1–2 hours. You may experience a brief power interruption (typically less than 30 minutes) during the swap.","After installation, the meter is activated remotely. Your energy supplier is notified automatically.","Within 1–2 billing cycles, your smart meter data will begin appearing on your electricity bill."]},{type:"paragraph",text:"The total process from request to activation typically takes 4–8 weeks. We strongly recommend starting this process at least 2 months before your planned solar installation date to ensure everything is ready."},{type:"heading",level:2,text:"Half-Hourly Settlement"},{type:"paragraph",text:"One of the most important features of a smart meter for solar customers is half-hourly settlement. This means the meter records your electricity import and export every 30 minutes, 24 hours a day, 365 days a year. This granular data serves several critical functions:"},{type:"bulletList",items:["CEG payments — Your energy supplier uses half-hourly data to calculate exactly how much electricity you exported, ensuring you are paid accurately for every unit","Time-of-use tariffs — Smart meters enable tariffs that charge different rates at different times of day (cheaper at night, more expensive during peak evening hours)","Demand response — Future energy schemes may reward you for shifting heavy electricity usage to times of high solar generation or low grid demand","Monitoring — You can track your solar generation, self-consumption, and export patterns through your energy supplier's app or third-party monitoring platforms"]},{type:"heading",level:2,text:"Time-of-Use Tariffs: A Hidden Benefit"},{type:"paragraph",text:"Smart meters unlock access to time-of-use (ToU) electricity tariffs, which charge different prices depending on the time of day. For solar panel owners, ToU tariffs offer a significant additional saving opportunity:"},{type:"bulletList",items:["Day rate (8am–11pm): Standard electricity price, typically €0.35–€0.45/kWh — this is when your solar panels are generating and offsetting your usage","Night rate (11pm–8am): Discounted price, typically €0.20–€0.25/kWh — perfect for charging EVs or solar batteries on cheap power","Peak rate (5pm–7pm): Some tariffs charge a premium during the evening peak — with solar, you can avoid this by using stored battery power"]},{type:"paragraph",text:"For households with an electric vehicle or a solar battery, a time-of-use tariff can save €300–€500 per year by shifting heavy charging to the cheap night-rate window. Without a smart meter, you cannot access these tariffs."},{type:"heading",level:2,text:"The Full Process: Smart Meter to CEG Registration"},{type:"paragraph",text:"To help you visualise the complete journey from smart meter to earning CEG payments, here is the end-to-end process:"},{type:"numberedList",items:["Request smart meter from ESB Networks (if you don't already have one)","Smart meter installed and activated (4–8 weeks from request)","Solar panels installed by SEAI-registered installer (1–2 days)","Installer registers your system with ESB Networks as a microgeneration unit","Contact your energy supplier to inform them of your solar installation","Supplier switches your account to a CEG-inclusive tariff","First CEG payment appears on your electricity bill (2–4 billing cycles after registration)"]},{type:"callout",variant:"info",title:"Don't Worry — It Is Easier Than It Sounds",body:"Most solar installers handle steps 4–6 on your behalf as part of their installation package. Your main responsibility is ensuring you have a smart meter before installation day. Everything else can typically be managed by your installer."},{type:"divider"},{type:"cta",text:"Check Your Smart Meter Status — Start Your Solar Journey",href:"/#calculator"}]},{slug:"how-many-solar-panels-do-i-need-ireland",title:"How Many Solar Panels Do I Need in Ireland?",image:"/blog-solar-installation.webp",excerpt:"A complete guide to sizing your solar system — from single-person apartments to large family homes. Includes a household size calculator, roof space guide, and budget-conscious strategies.",category:"guides",date:"2 Apr 2026",readTime:"9 min read",author:"Cal O'Reilly",iconBg:"bg-sky-400/10",iconColor:"text-sky-400",content:[{type:"heading",level:2,text:"The Most Important Number: Your Annual Electricity Usage"},{type:"paragraph",text:'Before we talk about panels, roof space, or budgets, there is one number that matters more than anything else: your annual electricity consumption in kilowatt-hours (kWh). This single figure, which you can find on your electricity bill (usually on the second page, labelled "Annual Consumption" or "kWh Usage"), determines the size of solar system you need and the savings you can expect.'},{type:"callout",variant:"tip",title:"Check Your Bill Now",body:"Find your annual usage in kWh (usually on the second page of your electricity bill). This is the single most important number for sizing your solar system. A typical Irish household uses 4,200 kWh per year."},{type:"paragraph",text:"The typical Irish household consumes approximately 4,200 kWh of electricity per year. However, this average masks a wide range. A single person in a small apartment might use just 2,000 kWh, while a large family with electric heating, an EV, and all the usual appliances could easily exceed 7,000 kWh. Your system should be sized to match your actual consumption — not your neighbour's."},{type:"heading",level:2,text:"System Sizing by Household Size"},{type:"paragraph",text:"While every home is different, household size is the strongest predictor of electricity consumption. Here is a detailed sizing guide based on the number of occupants and typical usage patterns in Ireland:"},{type:"table",headers:["Household Size","Annual Usage (kWh)","Recommended System","Number of Panels","Est. Annual Generation"],rows:[["1–2 people (low usage)","2,500–3,500 kWh","3–4 kWp","8–10 panels","2,700–3,600 kWh"],["1–2 people (medium usage)","3,500–4,500 kWh","4–5 kWp","10–13 panels","3,600–4,500 kWh"],["3–4 people","4,000–5,000 kWh","5–6 kWp","13–16 panels","4,500–5,400 kWh"],["5+ people","5,000–6,500 kWh","7–10 kWp","18–26 panels","6,300–9,000 kWh"],["EV + heat pump home","7,000–10,000 kWh","8–12 kWp","20–32 panels","7,200–10,800 kWh"]]},{type:"paragraph",text:"These recommendations assume a south-facing roof at approximately 35° pitch, which is optimal for Irish conditions. If your roof faces east or west, you will need roughly 15–20% more panels to achieve the same annual generation. The recommended system sizes are designed to cover a significant portion of your annual usage while avoiding severe over-generation, which would mean exporting large amounts of electricity at the lower CEG rate rather than using it yourself."},{type:"heading",level:2,text:"Understanding kWp, Panels, and Generation"},{type:"paragraph",text:"Solar panel systems are measured in kilowatt-peak (kWp), which represents the maximum power output under standard test conditions. A modern residential solar panel typically has a capacity of 350–430 watts (0.35–0.43 kWp). To calculate the number of panels you need, divide your target system size by the individual panel wattage."},{type:"bulletList",items:["A 400W panel is the most common choice for Irish residential installations in 2026","A 4kWp system requires approximately 10 panels (10 × 400W = 4,000W = 4kWp)","A 6kWp system requires approximately 15 panels (15 × 400W = 6,000W = 6kWp)","Each panel measures approximately 1.7m tall by 1.0m wide, requiring about 1.7m² of roof space","You should allow approximately 10cm gaps between panels for mounting rails and ventilation"]},{type:"heading",level:2,text:"Roof Space Requirements"},{type:"paragraph",text:"Roof space is often the limiting factor for solar installations in Ireland, particularly on smaller homes or properties with dormer windows, chimneys, or rooflights. Here is a practical guide to the roof space you will need:"},{type:"table",headers:["System Size","Number of Panels","Roof Space Needed (with gaps)","Minimum Roof Dimensions"],rows:[["3 kWp","8 panels","~15 m²","4m × 4m clear area"],["4 kWp","10 panels","~19 m²","5m × 4m clear area"],["6 kWp","15 panels","~28 m²","7m × 4m clear area"],["8 kWp","20 panels","~38 m²","10m × 4m clear area"],["10 kWp","25 panels","~47 m²","12m × 4m clear area"]]},{type:"paragraph",text:"These calculations include the 10cm gaps between panels and a small border around the array for mounting rails and edge clearance. If your roof has multiple planes (as most Irish homes do), you may be able to spread panels across two different roof faces — for example, some on the south-east and some on the south-west — which can work well and actually improve self-consumption by extending your generation window across more hours of the day."},{type:"heading",level:2,text:"How Roof Orientation Affects Sizing"},{type:"paragraph",text:"The direction your roof faces has a significant impact on how much electricity your panels generate. A south-facing roof at 35° pitch is the gold standard in Ireland, but not every home has this luxury. Here is how different orientations affect your system sizing:"},{type:"bulletList",items:["South-facing (180°) — Produces 100% of rated capacity. The optimal orientation in Ireland. You need fewer panels to hit your generation target.","South-east or south-west (135° or 225°) — Produces 90–95% of rated capacity. Slightly fewer panels needed than east/west, and a broader generation window.","East-facing (90°) — Produces 80–85% of rated capacity. Peaks in the morning. Good for morning usage patterns. Add 15–20% more panels to compensate.","West-facing (270°) — Produces 80–85% of rated capacity. Peaks in the afternoon. Good for households that are out during the day. Add 15–20% more panels.","North-facing (0°) — Produces 50–55% of rated capacity. Generally not recommended unless combined with a south-facing array. Requires nearly double the panels for the same output."]},{type:"heading",level:2,text:"Budget-Conscious Approach: Start Small, Expand Later"},{type:"paragraph",text:"If your budget does not stretch to your ideal system size right now, do not worry — solar systems are highly expandable. One of the most popular strategies among Irish homeowners is to start with a smaller system (typically 4kWp) and add more panels later as finances allow."},{type:"paragraph",text:"There are a few things to consider with this approach:"},{type:"bulletList",items:["Inverter capacity — Your installer should fit an inverter that is oversized relative to your initial panel count, leaving room for expansion. For example, if you start with 10 panels (4kWp), a 6kW inverter would allow you to add up to 5 more panels later without replacing the inverter.","Grant timing — The SEAI grant is per property, not per installation. If you claim the €1,800 grant for your initial system, you cannot claim it again when you expand. Factor the full grant into your initial installation.","Roof planning — When designing your initial system, ask your installer to plan the mounting rails for the maximum potential array, even if only some positions are filled initially. This makes expansion much cheaper later.","Cost of expansion — Adding panels to an existing system typically costs €300–€500 per panel (less than the initial installation cost because the inverter, scaffolding, and electrical infrastructure are already in place)."]},{type:"callout",variant:"info",title:"Use Our Quick Savings Calculator",body:"Want a personalised estimate based on your actual electricity usage and roof characteristics? Our Quick Savings Calculator on the homepage provides tailored system size recommendations, cost estimates, and projected savings — all in under 60 seconds."},{type:"heading",level:2,text:"Key Takeaways"},{type:"numberedList",items:["Start with your annual electricity usage (find it on your electricity bill) — this is the most important factor","A 3–4kWp system suits 1–2 person homes, a 5–6kWp system suits 3–4 person homes, and a 7–10kWp system suits larger families or homes with EVs and heat pumps","Each panel requires approximately 1.7m² of roof space plus gaps — measure your available roof area before getting quotes","South-facing roofs are optimal, but east and west-facing roofs are still highly viable (80–85% output)","If budget is tight, start with 4kWp and expand later — just ensure your inverter and mounting rails are sized for future expansion","Use our Quick Savings Calculator for a personalised system size recommendation"]},{type:"divider"},{type:"cta",text:"Calculate Your Ideal System Size — Free Solar Assessment",href:"/#calculator"}]},{slug:"best-time-of-year-to-get-solar-panels-ireland",title:"Best Time of Year to Get Solar Panels in Ireland",image:"/blog-solar-installation.webp",excerpt:"Is there an ideal season to install solar panels? We break down month-by-month generation data, seasonal advantages, and SEAI processing times to help you decide when to go solar.",category:"savings",date:"25 Mar 2026",readTime:"7 min read",author:"Cal O'Reilly",iconBg:"bg-emerald-400/10",iconColor:"text-emerald-400",content:[{type:"heading",level:2,text:"Spoiler: Any Time Is a Good Time"},{type:"paragraph",text:"Let us start with the most important point: there is no bad time to install solar panels in Ireland. Every month you have panels on your roof is a month of free electricity you are generating. The question is not whether to wait — it is whether there are strategic advantages to certain seasons that maximise your first-year returns. And the answer is yes, there are."},{type:"paragraph",text:"The main factor to consider is this: solar generation in Ireland varies enormously by season. A 4kWp south-facing system will generate roughly 380 kWh in June but only 70 kWh in December — a five-fold difference. If you install in spring, you immediately start capturing the highest-generation months and maximise your first-year savings. Install in December, and your first few months of generation will be relatively modest."},{type:"callout",variant:"stat",title:"Timing Matters",body:"Installing in March versus December means an extra 1,500 kWh in your first year — worth roughly €315 in electricity savings. That is the equivalent of 3–4 months of free electricity just from choosing the right installation month."},{type:"heading",level:2,text:"Month-by-Month Generation Data"},{type:"paragraph",text:"To understand the seasonal impact, here is the actual month-by-month generation data for a typical 4kWp south-facing solar PV system in Ireland. These figures are based on long-term meteorological averages from Met Éireann and SEAI data:"},{type:"table",headers:["Month","Expected Generation (kWh)","% of Annual Total","Daily Average (kWh)"],rows:[["January","80 kWh","2.6%","2.6"],["February","120 kWh","3.9%","4.3"],["March","200 kWh","6.6%","6.5"],["April","300 kWh","9.9%","10.0"],["May","370 kWh","12.2%","11.9"],["June","380 kWh","12.5%","12.7"],["July","380 kWh","12.5%","12.3"],["August","350 kWh","11.6%","11.3"],["September","260 kWh","8.6%","8.7"],["October","170 kWh","5.6%","5.5"],["November","100 kWh","3.3%","3.3"],["December","70 kWh","2.3%","2.3"],["Annual Total","2,780 kWh","100%","7.6"]]},{type:"paragraph",text:"The data tells a clear story. From April through September, Ireland receives 80% of its annual solar irradiation in just six months. October through March accounts for the remaining 20%. This is the fundamental reason why spring installation is optimal — you capture the entire high-generation season from day one."},{type:"heading",level:2,text:"Season-by-Season Analysis"},{type:"heading",level:3,text:"Spring (March–May): The Best Season"},{type:"paragraph",text:"Spring is widely considered the best time to install solar panels in Ireland, and for good reason. The SEAI grant approval process takes approximately 4–6 weeks, meaning if you apply in February or early March, your system will be installed and generating by April — just as the generation curve begins its steep upward climb. By installing in spring, you capture the entire April-to-September high-generation window in your first year."},{type:"bulletList",items:["Days are getting longer — your generation increases every week","Weather is typically mild — good conditions for installation (scaffolding, roof work)","Installers are moderately busy — lead times of 2–4 weeks are common, not the 6–8 weeks of peak summer","Maximum first-year generation — you capture nearly all of the high-output months"]},{type:"heading",level:3,text:"Summer (June–August): Immediate High Output"},{type:"paragraph",text:"Summer installation means your panels start generating at their maximum potential from day one. This is psychologically satisfying — you can see your inverter hitting its peak output within hours of being switched on. However, there are some trade-offs:"},{type:"bulletList",items:["Installers are at their busiest — lead times can stretch to 6–8 weeks, and you may pay a slight premium","You miss the March–May generation window — this costs you approximately 870 kWh of potential first-year generation","Scaffold work in hot weather can be slower — roof surface temperatures can reach 50°C+ on sunny days","Despite these drawbacks, summer generation is excellent and your system will be fully productive immediately"]},{type:"heading",level:3,text:"Autumn (September–November): Still Worthwhile"},{type:"paragraph",text:"Autumn is a pragmatic time to install solar panels. Generation is declining but still meaningful — September alone produces 260 kWh from a 4kWp system, more than December and January combined. Installer availability improves as the summer rush subsides, and you may be able to negotiate slightly better pricing."},{type:"paragraph",text:"The main disadvantage is that you miss the entire summer peak. However, the SEAI grant does not expire at the end of the year, and panels generate electricity in every month. An autumn installation means you start collecting savings immediately rather than waiting until the following spring."},{type:"heading",level:3,text:"Winter (December–February): Not Ideal, But Not Wrong"},{type:"paragraph",text:"Winter is the least popular time for solar installation, and the reasons are understandable: short days, poor weather, and low generation. However, it is not as bad as many people assume:"},{type:"bulletList",items:["Installers are least busy — shortest lead times (1–2 weeks) and potential for discounted pricing","Panels still generate — even in December, a 4kWp system produces approximately 70 kWh, enough to offset a portion of your higher winter electricity bills","The SEAI grant process continues year-round — there is no seasonal suspension of grant applications","Installation conditions — while weather can delay installation, most installers work year-round and monitor forecasts to schedule work on dry days"]},{type:"paragraph",text:'If you install in January, by the time your system is fully operational (factoring in 4–6 weeks for grant approval and scheduling), it will be late February or early March — just as generation begins to climb. The "lost" generation from January and February is relatively small (approximately 200 kWh combined).'},{type:"heading",level:2,text:"SEAI Processing Times"},{type:"paragraph",text:"The SEAI grant application process typically takes 4–6 weeks from submission to receiving your grant offer letter. After installation, you need a further 1–2 weeks to gather completion documents, and then 6–8 weeks for the grant payment to be processed. Here is the full timeline:"},{type:"table",headers:["Step","Duration","Cumulative Time"],rows:[["Get quotes and choose installer","2–3 weeks","2–3 weeks"],["Apply for SEAI grant","4–6 weeks","6–9 weeks"],["Schedule installation","2–4 weeks","8–13 weeks"],["Installation day","1–2 days","~13 weeks"],["Submit completion documents","1–2 weeks","~15 weeks"],["Receive grant payment","6–8 weeks","~21 weeks (5 months)"]]},{type:"paragraph",text:"This means that if you start the process in early February, you could have your panels installed and generating by late April, with the grant payment arriving by early July. The total end-to-end timeline is approximately 5 months, which is why starting early in the year is so advantageous."},{type:"heading",level:2,text:"The Cost of Waiting"},{type:"paragraph",text:"Every month you delay installing solar panels is a month of free electricity you are not getting. With the average Irish household paying approximately €0.40/kWh for electricity, even a modest winter month of 100 kWh generation would save you €40. Over a full year of waiting, that is €1,100 in savings you have permanently lost — not borrowed, but lost forever."},{type:"callout",variant:"tip",title:"Stop Waiting, Start Saving",body:"The best time to install solar panels was last year. The second best time is today. Whatever month it is, starting the process now means your system will be generating sooner. Every day of delay is a day of missed savings."},{type:"divider"},{type:"cta",text:"Start Your Solar Journey Today — Get a Free Quote",href:"/#calculator"}]},{slug:"solar-panels-rental-property-landlord-guide",title:"Solar Panels for Rental Properties: A Landlord's Guide",image:"/blog-solar-financing.webp",excerpt:"Can landlords get the SEAI solar grant? What about tenants? We cover everything property investors need to know about solar panels on rental properties in Ireland, including grants, BER benefits, and rent premiums.",category:"grants",date:"15 Mar 2026",readTime:"8 min read",author:"Cal O'Reilly",iconBg:"bg-amber-400/10",iconColor:"text-amber-400",content:[{type:"heading",level:2,text:"Can Landlords Get the SEAI Solar Grant?"},{type:"paragraph",text:"This is one of the most frequently asked questions we receive from property investors, and the answer depends on your specific situation. The SEAI solar PV grant is designed for homeowner-occupiers — people who live in the property as their principal private residence. This means:"},{type:"bulletList",items:["Yes — if you live in the property as your main home and install solar panels on it, you are eligible for the full €1,800 grant, regardless of whether you rent out individual rooms under the Rent a Room scheme","No — if the property is a buy-to-let investment that you do not live in, you are NOT eligible for the SEAI domestic solar PV grant","No — holiday homes and second homes are also not eligible, as the grant is restricted to your principal private residence"]},{type:"paragraph",text:"The eligibility criteria are clear: the SEAI grant is for owner-occupiers only. If you own multiple properties, you can claim the grant for the one you live in, but not for any rental properties. This is a source of frustration for many landlords who would like to improve the energy efficiency of their rental stock, but it is the current state of the scheme."},{type:"callout",variant:"info",title:"Rent-a-Room Exemption",body:"If you live in the property as your main home and rent out a room (or rooms) under the Rent a Room Scheme, you ARE eligible for the full €1,800 SEAI solar grant. The key test is whether the property is your principal private residence, not whether you have tenants."},{type:"heading",level:2,text:"Alternatives for Landlords"},{type:"paragraph",text:"While the domestic SEAI grant is not available for buy-to-let properties, there are alternative incentives and financial mechanisms that landlords can explore:"},{type:"heading",level:3,text:"Enhanced Capital Allowances (ECAs)"},{type:"paragraph",text:"For landlords who own commercial properties or mixed-use buildings, Enhanced Capital Allowances allow you to write off the full cost of qualifying energy-efficient equipment — including solar panels — against your taxable profits in the year of purchase. This can significantly reduce the effective cost of installation. ECAs are administered by the Sustainable Energy Authority of Ireland (SEAI) on behalf of the Revenue Commissioners."},{type:"heading",level:3,text:"Non-Domestic Microgen Scheme"},{type:"paragraph",text:"The SEAI operates a separate Non-Domestic Microgen Scheme for small-scale renewable energy installations on commercial and non-domestic properties. While primarily aimed at businesses, this scheme can be relevant for landlords of small commercial premises, offices, or mixed-use properties. The scheme offers support for solar PV systems up to 50kWp and includes assistance with grid connection and registration."},{type:"heading",level:3,text:"Tax Relief on Home Energy Upgrades"},{type:"paragraph",text:"While not specific to solar, landlords can claim tax relief on certain home energy upgrade expenditures as revenue expenses against rental income. The rules around what qualifies as a repair (revenue expense, deductible) versus an improvement (capital expense, not deductible) are complex, so always consult a tax professional before claiming. However, some solar-related electrical work may qualify as allowable expenses."},{type:"heading",level:2,text:"Benefits of Solar for Tenants"},{type:"paragraph",text:"Even without grant eligibility, installing solar panels on a rental property can deliver significant benefits — both for the landlord and the tenant. While the landlord bears the upfront cost, the advantages can be substantial:"},{type:"bulletList",items:["Lower electricity bills — tenants benefit directly from free solar electricity during the day, reducing their energy costs by €600–€1,200 per year depending on system size","More attractive property — homes with solar panels are increasingly sought after by environmentally conscious tenants and those looking to reduce living costs","Longer tenancies — tenants who benefit from lower energy bills are more likely to stay longer, reducing void periods and turnover costs for the landlord","Future-proofing — as energy regulations tighten, properties with solar panels will be better positioned to meet minimum energy efficiency standards"]},{type:"heading",level:2,text:"BER Rating Improvements"},{type:"paragraph",text:"One of the most compelling reasons for landlords to install solar panels on rental properties is the impact on the Building Energy Rating (BER). A better BER rating makes the property more attractive to tenants, may be required by future regulations, and can justify higher rents."},{type:"paragraph",text:"Solar PV installations typically improve a property's BER rating by 1–2 grades. For example, a D1-rated property could move to a C2 or C3 rating with a well-sized solar PV system. The exact improvement depends on the existing energy performance of the property, the size of the solar installation, and whether other energy efficiency measures are also implemented."},{type:"callout",variant:"stat",title:"BER and Tenant Demand",body:"Properties with a BER rating of C or above command 10–15% higher rents than equivalent properties with lower ratings, according to the Residential Tenancies Board. Solar panels are one of the most cost-effective ways to achieve this improvement."},{type:"heading",level:2,text:"Rent Premium Potential"},{type:"paragraph",text:"Irish rental market data increasingly shows that energy-efficient properties with solar panels command a measurable rent premium. Tenants are willing to pay more for homes with lower energy bills, particularly in a market where electricity costs have risen significantly in recent years."},{type:"paragraph",text:"Based on current market data from Daft.ie and the Residential Tenancies Board:"},{type:"bulletList",items:["Homes with solar panels can command an additional €50–€100 per month in rent, depending on the location and system size","Over a year, this represents €600–€1,200 in additional rental income","Combined with the tenant's electricity savings of €600–€1,200 per year, the total value proposition of solar is €1,200–€2,400 per year","For a 6kWp system costing approximately €9,500 (no grant), this means a payback period of 5–8 years purely from the rent premium — before counting any other benefits"]},{type:"heading",level:2,text:"Practical Considerations for Landlords"},{type:"paragraph",text:"If you are considering installing solar panels on a rental property, here are the practical factors to keep in mind:"},{type:"numberedList",items:["Installation access — You will need to coordinate with your tenant for scaffolding erection, installation day access (typically 1–2 days), and any necessary power shutdowns. Most installations require the electricity to be off for 1–2 hours.","Ownership and maintenance — The solar system is your property as the landlord, and you are responsible for its maintenance. Include clauses in the tenancy agreement regarding access for maintenance and any obligations on the tenant (e.g., not installing anything that shades the panels).","Insurance — Inform your landlord insurance provider that you have installed solar panels. Most policies will cover solar PV systems, but you need to ensure the system's value is included in your buildings cover.","Tenant electricity arrangements — If the property has a single electricity meter, the tenant benefits directly from the solar generation (lower bills). If the property has sub-metered units (e.g., a house split into flats), the arrangement needs to be clearly defined in the tenancy agreement.","CEG payments — If the tenant has their own electricity account and smart meter, they will receive the CEG export payments. If the electricity is included in the rent, the landlord effectively benefits. Clarify this in your tenancy agreement."]},{type:"heading",level:2,text:"2026 Developments: Grants for Rental Properties?"},{type:"paragraph",text:"There is growing political pressure to extend SEAI grant eligibility to rental properties. The government's Climate Action Plan recognises that the rental sector represents a significant proportion of Ireland's housing stock and that achieving national energy efficiency targets will require upgrades across all property types, not just owner-occupied homes."},{type:"paragraph",text:"In early 2026, the Department of Housing published a consultation document proposing a pilot scheme that would offer reduced grant levels for buy-to-let properties, subject to conditions such as minimum tenancy agreements of 3 years and BER improvement requirements. As of the time of writing, this proposal has not been confirmed or legislated for, and no specific details or timelines have been announced."},{type:"callout",variant:"tip",title:"Stay Informed",body:"The policy landscape for rental property energy upgrades is evolving rapidly. We recommend checking the SEAI website regularly or subscribing to their newsletter for the latest grant announcements. If a rental property grant scheme is introduced, it is likely to be announced as part of a budget or climate action update."},{type:"heading",level:2,text:"Is It Worth It Without the Grant?"},{type:"paragraph",text:"Even without the €1,800 SEAI grant, installing solar panels on a rental property can be a sound investment. A 6kWp system costs approximately €9,500 (without grant) and generates roughly €1,000–€1,400 per year in combined electricity savings and CEG payments. If the property commands a rent premium of €75/month (€900/year), the total annual benefit is approximately €1,900–€2,300, giving a payback period of 4–5 years. Over 25 years, the net profit could exceed €30,000."},{type:"paragraph",text:"For landlords looking to differentiate their properties in a competitive rental market, improve tenant retention, and future-proof their investments against tightening energy regulations, solar panels are a practical and financially attractive option — grant or no grant."},{type:"divider"},{type:"cta",text:"Explore Solar Options for Your Property — Get Expert Advice",href:"/#calculator"}]}];function c(a){return b.find(b=>b.slug===a)}function d(a,e=3){let f=c(a);if(!f)return b.slice(0,e);let g=b.filter(b=>b.category===f.category&&b.slug!==a);if(g.length>=e)return g.slice(0,e);let h=b.filter(b=>b.slug!==a&&!g.includes(b));return[...g,...h].slice(0,e)}a.s(["articles",0,b,"getArticleBySlug",()=>c,"getRelatedArticles",()=>d])}];

//# sourceMappingURL=src_lib_blog-data_ts_4db234bb._.js.map